/*
 * CONCEPT 10 — MODERN CHRISTMAS MOSAIC GREETING
 * Original procedural Canvas 2D artwork. No dependencies or external assets.
 * 25 seconds / 2 scenes / 16:9 / responsive FHD, QHD and UHD.
 * Scene 1: modular tree, gift, bell and snowflake tiles beside Merry Christmas.
 * Scene 2: the tiles form a mosaic frame around Joy, Peace & Warm Wishes.
 * Tiles follow separate vertical and horizontal grid moves. New frame accents
 * fade in only after their slots are free, then leave before the return move.
 * Pass time in SECONDS. Each frame is independent. The loop closes at 25 s.
 * No glow, bloom, blur, aura, DOM, imports, timers or animation scheduler.
 *
 * HOST VIDEO EXPORT REFERENCE:
 * 3840 x 2160, 60 fps, 1500 frames, frame times 0/60 through 1499/60.
 * H.264 CBR 100 Mbps: -c:v libx264 -preset slow -pix_fmt yuv420p
 * -b:v 100M -minrate 100M -maxrate 100M -bufsize 200M
 * -x264-params "nal-hrd=cbr:force-cfr=1:filler=1" -movflags +faststart
 * Verify the actual video stream with ffprobe; retain at least 100 Mbps.
 * Canvas supplies frames. This source does not encode or set video bitrate.
 */

function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !Number.isFinite(width) ||
      !Number.isFinite(height) || width <= 0 || height <= 0) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;

  const color = {
    background: '#ECE7DC', backgroundBottom: '#E5DFD3',
    blue: '#274C96', blueDark: '#203E79', bluePale: '#DCE2EA',
    coral: '#CB6757', coralPale: '#ECCBC1',
    cream: '#F5EEDD', creamLight: '#FCF6E9',
    gold: '#B99B62', goldLight: '#DFC99B',
    border: '#CBBCA7', muted: '#68707A'
  };

  function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }
  function smooth(value) {
    const u = clamp(value, 0, 1);
    return u * u * u * (u * (u * 6 - 15) + 10);
  }
  function ramp(low, high, value) { return smooth((value - low) / (high - low)); }
  function lerp(a, b, amount) { return a + (b - a) * amount; }

  const transition = ramp(0.64, 1, sceneProgress);
  const sceneMix = currentScene === 0 ? transition : 1 - transition;
  const travel = clamp((sceneProgress - 0.64) / 0.36, 0, 1);
  const layoutProgress = currentScene === 0 ? travel : 1 - travel;
  const verticalMove = ramp(0.0, 0.44, layoutProgress);
  const horizontalMove = ramp(0.48, 0.88, layoutProgress);
  const firstTitleAlpha = 1 - ramp(0.08, 0.34, sceneMix);
  const secondTitleAlpha = ramp(0.58, 0.88, sceneMix);
  const frameAccentAlpha = ramp(0.90, 1.0, layoutProgress);
  const tileSize = 156;

  const modules = [
    {kind:'tree',x:237,y:335,tx:345,ty:200,bg:color.blue,fg:color.cream},
    {kind:'snow',x:449,y:335,tx:755,ty:200,bg:color.cream,fg:color.blue},
    {kind:'quarter',x:237,y:540,tx:237,ty:540,bg:color.cream,fg:color.blue},
    {kind:'dots',x:449,y:540,tx:449,ty:540,bg:color.bluePale,fg:color.blue},
    {kind:'gift',x:237,y:745,tx:345,ty:880,bg:color.coral,fg:color.cream},
    {kind:'bell',x:449,y:745,tx:755,ty:880,bg:color.gold,fg:color.blue},
    {kind:'gift',x:1471,y:335,tx:1165,ty:200,bg:color.coral,fg:color.cream},
    {kind:'bell',x:1683,y:335,tx:1575,ty:200,bg:color.cream,fg:color.blue},
    {kind:'arcs',x:1471,y:540,tx:1471,ty:540,bg:color.cream,fg:color.blue},
    {kind:'triangles',x:1683,y:540,tx:1683,ty:540,bg:color.blue,fg:color.cream},
    {kind:'tree',x:1471,y:745,tx:1165,ty:880,bg:color.blue,fg:color.cream},
    {kind:'snow',x:1683,y:745,tx:1575,ty:880,bg:color.coralPale,fg:color.blue}
  ];

  const frameAccents = [
    {kind:'quarter',x:550,y:200,bg:color.coralPale,fg:color.blue},
    {kind:'arcs',x:960,y:200,bg:color.bluePale,fg:color.blue},
    {kind:'dots',x:1370,y:200,bg:color.cream,fg:color.blue},
    {kind:'dots',x:550,y:880,bg:color.cream,fg:color.blue},
    {kind:'quarter',x:960,y:880,bg:color.coral,fg:color.cream},
    {kind:'triangles',x:1370,y:880,bg:color.bluePale,fg:color.blue}
  ];

  function roundedRect(x, y, w, h, r) {
    const radius = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + radius, y);
    ctx.lineTo(x + w - radius, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
    ctx.lineTo(x + w, y + h - radius);
    ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
    ctx.lineTo(x + radius, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
    ctx.lineTo(x, y + radius); ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
  }

  function circle(x, y, radius, fill) {
    ctx.beginPath(); ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = fill; ctx.fill();
  }

  function triangle(x0, y0, x1, y1, x2, y2, fill) {
    ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
  }

  function star(x, y, outer, inner, angle, fill) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = angle - Math.PI / 2 + i * Math.PI / 5;
      const r = i % 2 === 0 ? outer : inner;
      const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
  }

  function fitText(text, x, baseline, size, maxWidth, fill, weight) {
    const family = 'Arial, Helvetica, sans-serif';
    ctx.font = weight + ' ' + size + 'px ' + family;
    const m = ctx.measureText(text);
    const measured = Math.max(m.width, (m.actualBoundingBoxLeft || 0) + (m.actualBoundingBoxRight || 0));
    const fitted = measured > maxWidth ? size * maxWidth / measured : size;
    ctx.font = weight + ' ' + fitted + 'px ' + family;
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = fill;
    ctx.fillText(text, x, baseline);
  }

  function trackedText(text, x, baseline, size, tracking, maxWidth, fill) {
    ctx.save(); ctx.font = size + 'px Arial, Helvetica, sans-serif';
    const letters = Array.from(text), widths = letters.map(letter => ctx.measureText(letter).width);
    const total = widths.reduce((a, b) => a + b, 0) + (letters.length - 1) * tracking;
    const factor = Math.min(1, maxWidth / Math.max(1, total));
    ctx.translate(x, baseline); ctx.scale(factor, factor);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = fill;
    let cursor = -total / 2;
    for (let i = 0; i < letters.length; i++) {
      ctx.fillText(letters[i], cursor, 0); cursor += widths[i] + tracking;
    }
    ctx.restore();
  }

  function treeIcon(module, id) {
    star(0, -47, 7, 3.3, 0.035 * Math.sin(phase * 2 + id * 0.29), color.goldLight);
    // The tier gaps remain open, so the three geometric branches stay distinct.
    triangle(0,-30,-19,-9,19,-9,module.fg);
    triangle(0,-5,-32,17,32,17,color.goldLight);
    triangle(0,21,-45,44,45,44,module.fg);
    roundedRect(-5, 50, 10, 10, 2); ctx.fillStyle = color.goldLight; ctx.fill();
    circle(-13, 11, 2.5, color.blue); circle(13, 11, 2.5, color.blue);
    circle(-20, 35, 2.8, color.coral); circle(20, 35, 2.8, color.coral);
  }

  function giftIcon(module, id) {
    roundedRect(-40, -4, 80, 56, 5); ctx.fillStyle = module.fg; ctx.fill();
    const ribbon = color.blue;
    ctx.fillStyle = ribbon; ctx.fillRect(-7, -4, 14, 56);
    roundedRect(-44, -13, 88, 14, 4); ctx.fillStyle = color.goldLight; ctx.fill();
    ctx.fillStyle = ribbon; ctx.fillRect(-7, -13, 14, 14);
    for (const x of [-26, 26]) {
      circle(x, 16, 2.2, color.coral); circle(x, 34, 2.2, color.coral);
    }
    ctx.save(); ctx.translate(0, -16);
    ctx.rotate(0.009 * Math.sin(phase * 2 + id * 0.29));
    for (const side of [-1, 1]) {
      ctx.save(); ctx.scale(side, 1);
      ctx.beginPath(); ctx.moveTo(4, 0);
      ctx.bezierCurveTo(12, -8, 24, -20, 29, -13);
      ctx.bezierCurveTo(34, 0, 11, 3, 4, 0); ctx.closePath();
      ctx.moveTo(11, -2);
      ctx.bezierCurveTo(18, -7, 24, -13, 25, -10);
      ctx.bezierCurveTo(27, -4, 17, -2, 11, -2); ctx.closePath();
      ctx.fillStyle = module.fg; ctx.fill('evenodd'); ctx.restore();
    }
    roundedRect(-6, -4, 12, 10, 3); ctx.fillStyle = ribbon; ctx.fill();
    ctx.restore();
  }

  function bellIcon(module, id) {
    ctx.save(); ctx.translate(0, -34);
    ctx.rotate(0.015 * Math.sin(phase * 2 + id * 0.29)); ctx.translate(0, 34);
    roundedRect(-3.5, -44, 7, 15, 2); ctx.fillStyle = module.fg; ctx.fill();
    circle(0, -44, 5.5, module.fg);
    ctx.beginPath(); ctx.moveTo(0, -33);
    ctx.bezierCurveTo(-25, -33, -30, -17, -30, 5);
    ctx.quadraticCurveTo(-30, 23, -41, 30);
    ctx.lineTo(-45, 35); ctx.quadraticCurveTo(-46, 38, -42, 38);
    ctx.lineTo(42, 38); ctx.quadraticCurveTo(46, 38, 45, 35);
    ctx.lineTo(41, 30); ctx.quadraticCurveTo(30, 23, 30, 5);
    ctx.bezierCurveTo(30, -17, 25, -33, 0, -33); ctx.closePath();
    ctx.fillStyle = module.fg; ctx.fill();
    ctx.strokeStyle = color.goldLight; ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-17, -6); ctx.lineTo(-17, 9);
    ctx.moveTo(0, -17); ctx.lineTo(0, 6);
    ctx.moveTo(17, -6); ctx.lineTo(17, 9); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-31, 29); ctx.lineTo(31, 29); ctx.stroke();
    circle(0, 49, 6.5, module.fg);
    ctx.restore();
  }

  function snowIcon(module, id) {
    ctx.save(); ctx.rotate(0.027 * Math.sin(phase * 2 + id * 0.29));
    ctx.strokeStyle = module.fg; ctx.lineWidth = 3.0;
    ctx.beginPath();
    for (let arm = 0; arm < 6; arm++) {
      const a = -Math.PI / 2 + arm * TAU / 6;
      const ux = Math.cos(a), uy = Math.sin(a);
      ctx.moveTo(ux * 5, uy * 5); ctx.lineTo(ux * 46, uy * 46);
      for (const distance of [25, 37]) {
        const length = distance === 25 ? 10 : 8;
        const px = ux * distance, py = uy * distance;
        ctx.moveTo(px, py);
        ctx.lineTo(px + length * Math.cos(a + 2.25), py + length * Math.sin(a + 2.25));
        ctx.moveTo(px, py);
        ctx.lineTo(px + length * Math.cos(a - 2.25), py + length * Math.sin(a - 2.25));
      }
    }
    ctx.stroke(); circle(0, 0, 4.1, color.gold); ctx.restore();
  }

  function quarterPattern(module, id) {
    ctx.beginPath(); ctx.moveTo(-50, -6);
    ctx.arc(-50, -6, 44, -Math.PI / 2, 0); ctx.closePath();
    ctx.fillStyle = color.blue; ctx.fill();
    circle(28, -28, 22, color.gold);
    circle(28 + 5.5 * Math.cos(phase + id * 0.21),
      -28 + 5.5 * Math.sin(phase + id * 0.21), 3.8, color.cream);
    roundedRect(-50, 6, 44, 44, 2);
    ctx.fillStyle = module.bg === color.coral ? color.bluePale : color.coral; ctx.fill();
    triangle(6,50,50,50,50,6,module.fg);
  }

  function dotPattern(module, id) {
    const dx = 2.2 * Math.sin(phase + id * 0.21);
    const dy = 1.4 * Math.sin(phase * 2 + id * 0.21);
    for (let row = 0; row < 4; row++) for (let column = 0; column < 4; column++) {
      const fill = (row + column) % 4 === 0 ? color.coral : module.fg;
      circle(-36 + column * 24 + dx, -36 + row * 24 + dy, 4.2, fill);
    }
  }

  function arcPattern(module, id) {
    const radii = [46, 32, 18], inks = [color.blue, color.coral, color.gold];
    ctx.lineWidth = 8;
    for (let i = 0; i < radii.length; i++) {
      ctx.beginPath(); ctx.arc(0, 16, radii[i], Math.PI, TAU);
      ctx.strokeStyle = inks[i]; ctx.stroke();
    }
    for (let i = 0; i < 4; i++) {
      const y = 45 + 0.9 * Math.sin(phase + id * 0.21 + i * 0.3);
      circle(-36 + i * 24, y, 3.7, i % 2 ? color.gold : module.fg);
    }
  }

  function trianglePattern(module) {
    triangle(-52,-41,-7,-41,-7,2,color.goldLight);
    triangle(7,7,52,7,52,52,module.fg);
    circle(34, -28, 10, color.coral);
    roundedRect(-51, 20, 26, 26, 2); ctx.fillStyle = color.coral; ctx.fill();
  }

  function moduleTile(module, x, y, alpha, id) {
    if (alpha <= 0.0001) return;
    ctx.save(); ctx.globalAlpha = alpha; ctx.translate(x, y);
    roundedRect(-tileSize / 2, -tileSize / 2, tileSize, tileSize, 9);
    ctx.fillStyle = module.bg; ctx.fill();
    ctx.strokeStyle = module.bg === color.cream ? '#D2C3AD' : module.bg;
    ctx.lineWidth = 1.2; ctx.stroke();
    if (module.kind === 'tree') treeIcon(module, id);
    else if (module.kind === 'gift') giftIcon(module, id);
    else if (module.kind === 'bell') bellIcon(module, id);
    else if (module.kind === 'snow') snowIcon(module, id);
    else if (module.kind === 'quarter') quarterPattern(module, id);
    else if (module.kind === 'dots') dotPattern(module, id);
    else if (module.kind === 'arcs') arcPattern(module, id);
    else trianglePattern(module);
    ctx.restore();
  }

  function greeting(alpha, second) {
    if (alpha <= 0.0001) return;
    ctx.save(); ctx.globalAlpha = alpha;
    trackedText('CHRISTMAS GREETINGS', 960, 393, 14, 2.7, 536, color.muted);
    if (!second) {
      fitText('Merry', 960, 496, 80, 544, color.blue, '700');
      fitText('Christmas', 960, 590, 78, 548, color.blue, '700');
      trackedText('A SEASON TO CELEBRATE', 960, 686, 13, 2.3, 540, color.muted);
    } else {
      fitText('Joy, Peace', 960, 496, 69, 548, color.blue, '700');
      fitText('& Warm Wishes', 960, 590, 59, 548, color.blue, '700');
      trackedText('WISHING YOU A BEAUTIFUL SEASON', 960, 686, 12.5, 1.8, 542, color.muted);
    }
    ctx.restore();
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'rgba(0,0,0,0)'; ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]); ctx.lineDashOffset = 0;
  const background = ctx.createLinearGradient(0, 0, 0, height);
  background.addColorStop(0, color.background); background.addColorStop(1, color.backgroundBottom);
  ctx.fillStyle = background; ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit); ctx.lineCap = 'round'; ctx.lineJoin = 'round';

  // Fine print marks stay outside all tile paths and the greeting panel.
  ctx.strokeStyle = '#C8BBA6'; ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.moveTo(92, 142); ctx.lineTo(92, 92); ctx.lineTo(142, 92);
  ctx.moveTo(1778, 92); ctx.lineTo(1828, 92); ctx.lineTo(1828, 142);
  ctx.moveTo(92, 938); ctx.lineTo(92, 988); ctx.lineTo(142, 988);
  ctx.moveTo(1778, 988); ctx.lineTo(1828, 988); ctx.lineTo(1828, 938); ctx.stroke();

  for (let i = 0; i < modules.length; i++) {
    const module = modules[i];
    const x = lerp(module.x, module.tx, horizontalMove);
    const y = lerp(module.y, module.ty, verticalMove);
    moduleTile(module, x, y, 1, i);
  }
  for (let i = 0; i < frameAccents.length; i++) {
    const module = frameAccents[i];
    moduleTile(module, module.x, module.y, frameAccentAlpha, i + modules.length);
  }

  roundedRect(630, 325, 660, 430, 22);
  ctx.fillStyle = color.creamLight; ctx.fill();
  ctx.strokeStyle = color.border; ctx.lineWidth = 1.4; ctx.stroke();
  ctx.strokeStyle = color.gold; ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(830, 637); ctx.lineTo(913, 637);
  ctx.moveTo(1007, 637); ctx.lineTo(1090, 637); ctx.stroke();
  star(960, 637, 8.5, 4.0, 0, color.coral);
  greeting(firstTitleAlpha, false); greeting(secondTitleAlpha, true);
  ctx.restore();
}

/*
 * CONCEPT 09 — LAYERED CHRISTMAS FOREST GREETING
 * Original procedural Canvas 2D artwork. No external assets or dependencies.
 * 25 seconds / 2 scenes / 16:9 / responsive FHD, QHD and UHD.
 * Scene 1: Season's Greetings in an ivory arch amid three forest depths.
 * Scene 2: the forest opens into balanced sides around Merry & Bright and
 * a decorated Christmas tree. Snow, parallax and matte stars remain active.
 * Pass time in SECONDS. Every frame is independent. The loop closes at 25 s.
 * No glow, bloom, blur, aura, DOM, imports, timers or animation scheduler.
 *
 * HOST VIDEO EXPORT REFERENCE:
 * 3840 x 2160, 60 fps, 1500 frames, frame times 0/60 through 1499/60.
 * H.264 CBR 100 Mbps: -c:v libx264 -preset slow -pix_fmt yuv420p
 * -b:v 100M -minrate 100M -maxrate 100M -bufsize 200M
 * -x264-params "nal-hrd=cbr:force-cfr=1:filler=1" -movflags +faststart
 * Verify the actual video stream with ffprobe; retain at least 100 Mbps.
 * Canvas supplies frames. This source does not encode or set video bitrate.
 */

function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !Number.isFinite(width) ||
      !Number.isFinite(height) || width <= 0 || height <= 0) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;

  const color = {
    sky: '#214A47', skyBottom: '#315E52',
    ivory: '#F4F0D9', ink: '#315D50', gold: '#B49961',
    goldLight: '#DFC98D', snow: '#F1F4DF',
    farGround: '#668E7B', middleGround: '#ABC7AC',
    frontGround: '#E4EBD2', archEdge: '#C6B67D'
  };

  function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }
  function smooth(value) {
    const u = clamp(value, 0, 1);
    return u * u * u * (u * (u * 6 - 15) + 10);
  }
  function ramp(low, high, value) { return smooth((value - low) / (high - low)); }
  function fract(value) { return value - Math.floor(value); }

  const transition = ramp(0.78, 1, sceneProgress);
  const sceneMix = currentScene === 0 ? transition : 1 - transition;
  const firstTitleAlpha = 1 - ramp(0.12, 0.42, sceneMix);
  const secondTitleAlpha = ramp(0.60, 0.88, sceneMix);
  const treeAlpha = secondTitleAlpha;

  const layers = [
    { shift: 26, drift: 1.4, ground: color.farGround, pine: '#A0BEAA', shade: '#8DAD9A', snow: '#D3E1CC', trunk: '#739680', line: 1.5,
      profile: [676, 595, 635, 666], trees: [{x:218,w:60,h:138},{x:459,w:80,h:176}] },
    { shift: 36, drift: 2.4, ground: color.middleGround, pine: '#5D8B71', shade: '#4F7C66', snow: '#E4ECD5', trunk: '#47715A', line: 2.0,
      profile: [844, 757, 796, 829], trees: [{x:330,w:94,h:164},{x:580,w:96,h:188}] },
    { shift: 32, drift: 3.6, ground: color.frontGround, pine: '#306354', shade: '#265748', snow: '#E7EED6', trunk: '#426C55', line: 2.5,
      profile: [1004, 894, 932, 957], trees: [{x:186,w:118,h:246},{x:452,w:102,h:216}] }
  ];

  const skyStars = [
    {x:344,y:192,r:10},{x:608,y:142,r:7.3},{x:1271,y:232,r:8.8},
    {x:1558,y:248,r:9.2},{x:1760,y:410,r:6.5},{x:112,y:343,r:7.2}
  ];

  function roundedRect(x, y, w, h, r) {
    const radius = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + radius, y);
    ctx.lineTo(x + w - radius, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
    ctx.lineTo(x + w, y + h - radius);
    ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
    ctx.lineTo(x + radius, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
    ctx.lineTo(x, y + radius); ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
  }

  function circle(x, y, r, fill) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = fill; ctx.fill();
  }

  function star(x, y, outer, inner, angle, fill) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = angle - Math.PI / 2 + i * Math.PI / 5;
      const r = i % 2 === 0 ? outer : inner;
      const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
  }

  function fitText(text, x, baseline, size, maxWidth, fill, family) {
    ctx.font = size + 'px ' + family;
    const m = ctx.measureText(text);
    const measured = Math.max(m.width, (m.actualBoundingBoxLeft || 0) + (m.actualBoundingBoxRight || 0));
    ctx.font = (measured > maxWidth ? size * maxWidth / measured : size) + 'px ' + family;
    ctx.fillStyle = fill; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, x, baseline);
  }

