  star(960, badgeY, 10.5, 4, C.gold, 0.035 * Math.sin(phase));
  line(C.gold, 1.05, () => {
    ctx.moveTo(868, badgeY);
    ctx.lineTo(918, badgeY);
    ctx.moveTo(1002, badgeY);
    ctx.lineTo(1052, badgeY);
  });
  circle(852, badgeY, 1.8, C.gold);
  circle(1068, badgeY, 1.8, C.gold);
  star(960, 807 + 1.0 * Math.sin(phase), 7.5, 4, C.gold, 0);
  circle(940, 807 + 1.0 * Math.sin(phase), 1.5, C.gold);
  circle(980, 807 + 1.0 * Math.sin(phase), 1.5, C.gold);

  // These alpha intervals never intersect, preventing overprinted greetings.
  greeting(firstTitleAlpha, false);
  greeting(secondTitleAlpha, true);
  ctx.restore();
}

