  const cardH = 590;
  const envelopeX = 960;
  const envelopeY = 562;
  const envelopeW = 1000;
  const envelopeH = 342;
  const flapHeight = 310;
  const flapAngle = lerp(2.18, 2.94, letterMix) + 0.004 * Math.sin(phase * 2);
  const flapTipY = envelopeY + flapHeight * Math.cos(flapAngle);

  const C = {
    background: '#F5F0E7',
    ivory: '#FBF8EE',
    ivoryEdge: '#E7DECA',
    forest: '#325A4B',
    pine: '#527A60',
    sage: '#839D82',
    eucalyptus: '#A6B8A0',
    eucalyptusDark: '#819E88',
    gold: '#B39663',
    goldLight: '#D7C28D',
    goldDark: '#92764F',
    terracotta: '#BD7060',
    rustDark: '#A5594E',
    rustLight: '#CE8875',
    cranberry: '#AA4650',
    mutedInk: '#7B8670',
    ink: '#335A4C'
  };

  function line(color, thickness, build) {
    ctx.beginPath();
    build();
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function roundRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function triangle(ax, ay, bx, by, cx, cy, color) {
    ctx.beginPath();
    ctx.moveTo(ax, ay);
    ctx.lineTo(bx, by);
    ctx.lineTo(cx, cy);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function star(x, y, radius, color, points) {
    const n = points || 5;
    ctx.beginPath();
    for (let i = 0; i < n * 2; i++) {
      const a = -Math.PI / 2 + i * Math.PI / n;
      const r = i % 2 === 0 ? radius : radius * (n === 4 ? 0.30 : 0.46);
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function trackedText(text, x, baseline, size, tracking, color, maxWidth) {
    ctx.save();
    ctx.font = '500 ' + size + 'px Arial, Helvetica, sans-serif';
    const widths = [];
    let total = Math.max(0, text.length - 1) * tracking;
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      widths.push(w);
      total += w;
    }
    const fit = Math.min(1, maxWidth / Math.max(1, total));
    ctx.translate(x, baseline);
    ctx.scale(fit, fit);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color;
    let left = -total / 2;
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], left, 0);
      left += widths[i] + tracking;
    }
    ctx.restore();
  }

  function serifText(text, x, baseline, size, maxWidth) {
    ctx.save();
    const family = 'Georgia, "Times New Roman", serif';
    ctx.font = 'normal ' + size + 'px ' + family;
    const measured = ctx.measureText(text).width;
    const fitted = size * Math.min(1, maxWidth / Math.max(1, measured));
    ctx.font = 'normal ' + fitted + 'px ' + family;
    ctx.fillStyle = C.ink;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, x, baseline);
    ctx.restore();
  }

  function pineSprig(x, y, length, angle, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle + 0.009 * Math.sin(phase + id * 0.83));
    ctx.scale(length / 270, length / 270);
    line('#698167', 2.5, () => {
      ctx.moveTo(-135, 4);
      ctx.bezierCurveTo(-45, -6, 48, 9, 135, -5);
    });
    function needle(px, py, dx, dy, halfW) {
      const len = Math.sqrt(dx * dx + dy * dy);
      const nx = -dy / len * halfW;
      const ny = dx / len * halfW;
      ctx.moveTo(px, py);
      ctx.quadraticCurveTo(px + dx * 0.43 + nx, py + dy * 0.43 + ny, px + dx, py + dy);
      ctx.quadraticCurveTo(px + dx * 0.43 - nx, py + dy * 0.43 - ny, px, py);
      ctx.closePath();
    }
    line(C.pine, 1.5, () => {
      for (let i = 0; i < 6; i++) {
        const bx = -112 + i * 39;
        const reach = 35 + 14 * Math.sin(i * 0.58);
        for (let side = -1; side <= 1; side += 2) {
          ctx.moveTo(bx, 2);
          ctx.quadraticCurveTo(bx + 12, side * reach * 0.46, bx + 30, side * reach);
        }
      }
    });
    for (let pass = 0; pass < 3; pass++) {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const bx = -112 + i * 39;
        const reach = 35 + 14 * Math.sin(i * 0.58);
        for (let side = -1; side <= 1; side += 2) {
          if ((i + (side > 0 ? 1 : 0) + id) % 3 !== pass) continue;
          for (let k = 0; k < 5; k++) {
            const q = 0.18 + k * 0.175;
            const px = bx + 30 * q;
            const py = side * reach * q;
            const n = 23 - k * 1.8;
            needle(px, py, n * 0.08, side * n * 0.93, 2.2);
            needle(px, py, n * 0.98, side * n * 0.15, 2.1);
          }
        }
      }
      ctx.fillStyle = [C.forest, C.pine, C.sage][pass];
      ctx.fill();
    }
    ctx.restore();
  }

  function eucalyptusLeaf(x, y, angle, scale, lighter) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.scale(scale, scale);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(-15, -7, -18, -27, -4, -42);
    ctx.bezierCurveTo(9, -49, 24, -36, 22, -24);
    ctx.bezierCurveTo(22, -13, 10, -3, 0, 0);
    ctx.closePath();
    ctx.fillStyle = lighter ? C.eucalyptus : C.eucalyptusDark;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(4, -22, 4, -41);
    ctx.bezierCurveTo(16, -45, 24, -35, 22, -24);
    ctx.bezierCurveTo(22, -13, 10, -3, 0, 0);
    ctx.closePath();
    ctx.fillStyle = lighter ? '#BBC8AF' : '#96AE93';
    ctx.fill();
    line('#779073', 1, () => {
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(4, -21, 4, -35);
    });
    ctx.restore();
  }

  function eucalyptusSprig(x, y, length, angle, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle + 0.008 * Math.sin(phase + id));
    ctx.scale(length / 210, length / 210);
    line('#7A9376', 1.8, () => {
      ctx.moveTo(-105, 4);
      ctx.bezierCurveTo(-28, -9, 33, 12, 105, -4);
    });
    for (let i = 0; i < 7; i++) {
      const px = -82 + i * 25;
      const side = i % 2 === 0 ? -1 : 1;
      const py = side * 8;
      line('#7A9376', 1.3, () => {
        ctx.moveTo(px - 4, 0);
        ctx.lineTo(px, py);
      });
      eucalyptusLeaf(px, py, (side < 0 ? 0.42 : Math.PI - 0.42)
        + 0.016 * Math.sin(phase + i * 0.6 + id), 0.80 + 0.07 * (i % 3), i % 2 === 0);
    }
    ctx.restore();
  }

  function berryTwig(x, y, angle, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle + 0.009 * Math.sin(phase + id));
    const points = [[-22,-9,10],[3,-23,11],[26,-5,10],[10,19,10]];
    line('#6F886C', 1.8, () => {
      for (let i = 0; i < points.length; i++) {
        ctx.moveTo(-7, 36);
        ctx.quadraticCurveTo(-1, 11, points[i][0], points[i][1]);
      }
    });
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      circle(p[0], p[1] + 1, p[2], '#873F45');
      circle(p[0] - 0.6, p[1] - 1, p[2] - 0.7, C.cranberry);
      circle(p[0] - 3, p[1] - 4, 2, '#CE8077');
    }
    ctx.restore();
  }

  function ribbonBow(x, y, scale, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(0.020 * Math.sin(phase + id));
    ctx.scale(scale, scale);
    const tail = 1.5 * Math.sin(phase * 2 + id);
    ctx.beginPath();
    ctx.moveTo(-7, 7);
    ctx.bezierCurveTo(-15, 31, -24 + tail, 54, -38 + tail, 81);
    ctx.lineTo(-20 + tail, 77);
    ctx.lineTo(-10 + tail, 88);
    ctx.bezierCurveTo(1, 48, 6, 21, 4, 8);
    ctx.closePath();
    ctx.fillStyle = '#914A42';
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(4, 6);
    ctx.bezierCurveTo(10, 35, 30 + tail, 58, 43 + tail, 72);
    ctx.lineTo(26 + tail, 72);
    ctx.lineTo(16 + tail, 83);
    ctx.bezierCurveTo(6, 63, -6, 29, -7, 8);
    ctx.closePath();
    ctx.fillStyle = '#BC6756';
    ctx.fill();
    for (let side = -1; side <= 1; side += 2) {
      ctx.beginPath();
      ctx.moveTo(side * 7, -3);
      ctx.bezierCurveTo(side * 31, -32, side * 69, -35, side * 61, -11);
      ctx.bezierCurveTo(side * 68, 13, side * 33, 25, side * 7, 8);
      ctx.closePath();
      ctx.fillStyle = '#B96D5A';
      ctx.fill();
      line('#935346', 1.4, () => {
        ctx.moveTo(side * 10, 1);
        ctx.quadraticCurveTo(side * 30, -8, side * 47, -13);
      });
    }
    roundRect(-10, -10, 20, 26, 5);
    ctx.fillStyle = '#965348';
    ctx.fill();
    roundRect(-6, -8, 12, 22, 4);
    ctx.fillStyle = '#BD7862';
    ctx.fill();
    ctx.restore();
  }

  function snowflake(x, y, radius, id, alpha) {
    ctx.save();
    ctx.translate(x + 2 * Math.sin(phase + id), y + 2.4 * Math.cos(phase + id));
    ctx.rotate(0.07 * Math.sin(phase + id * 0.7));
    ctx.globalAlpha *= alpha;
    line('#B8AD92', 1.45, () => {
      for (let i = 0; i < 6; i++) {
        const a = i * Math.PI / 3;
        const ux = Math.cos(a), uy = Math.sin(a);
        ctx.moveTo(0, 0);
        ctx.lineTo(ux * radius, uy * radius);
        const bx = ux * radius * 0.60, by = uy * radius * 0.60;
        for (let side = -1; side <= 1; side += 2) {
          ctx.moveTo(bx, by);
          ctx.lineTo(bx - ux * radius * 0.18 - uy * side * radius * 0.18,
            by - uy * radius * 0.18 + ux * side * radius * 0.18);
        }
      }
    });
    ctx.restore();
  }

  function cardStamp() {
    const x = 268, y = 30, w = 52, h = 65;
    roundRect(x, y, w, h, 4);
    ctx.fillStyle = '#EAECDC';
    ctx.fill();
    roundRect(x + 5, y + 5, w - 10, h - 10, 2);
    ctx.strokeStyle = '#A8B194';
    ctx.lineWidth = 1.1;
    ctx.stroke();
    star(x + w / 2, y + 29, 11.5, '#A48B5B', 5);
    line('#A8B194', 1.2, () => {
      ctx.moveTo(x + 15, y + 49);
      ctx.lineTo(x + w - 15, y + 49);
    });
    for (let i = 0; i < 5; i++) {
      circle(x - 0.5, y + 9 + i * 11.5, 1.5, C.ivory);
      circle(x + w + 0.5, y + 9 + i * 11.5, 1.5, C.ivory);
    }
  }

  function cardGreeting(alpha, second) {
    if (alpha <= 0.0001) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.translate(0, (second ? 1 : -1) * 7 * (1 - alpha));
    serifText(second ? 'Sending' : 'Merry', 0, 163, second ? 68 : 77, 610);
    serifText(second ? 'Warm Wishes' : 'Christmas', 0, 255, second ? 86 : 98, 650);
    line(C.gold, 1.1, () => {
      ctx.moveTo(-110, 286);
      ctx.lineTo(-25, 286);
      ctx.moveTo(25, 286);
      ctx.lineTo(110, 286);
    });
    star(0, 286, 5.4, C.gold, 4);
    trackedText(second ? 'A LITTLE JOY, SENT WITH LOVE' : 'WITH LOVE THIS CHRISTMAS',
      0, 330, 12.5, 2.3, C.mutedInk, 530);
    ctx.restore();
  }

  function card() {
    ctx.save();
    ctx.translate(cardX, cardTop);
    // A small solid offset gives paper depth; there is no blurred shadow.
    roundRect(-cardW / 2 + 3, 5, cardW, cardH, 14);
    ctx.fillStyle = '#D6CDBB';
    ctx.fill();
    roundRect(-cardW / 2, 0, cardW, cardH, 14);
    const paper = ctx.createLinearGradient(0, 0, 0, cardH);
    paper.addColorStop(0, '#FCFAF1');
    paper.addColorStop(0.55, '#FAF7EC');
    paper.addColorStop(1, '#F4EDDC');
    ctx.fillStyle = paper;
    ctx.fill();
    roundRect(-cardW / 2 + 19, 19, cardW - 38, cardH - 38, 7);
    ctx.strokeStyle = '#D9CBB0';
    ctx.lineWidth = 1.1;
    ctx.stroke();
    cardStamp();
    trackedText('CHRISTMAS GREETINGS', 0, 53, 12.5, 2.4, C.mutedInk, 435);
    star(0, 90, 7, C.gold, 4);

    // This printed row is physically hidden in scene 1 and revealed as the
    // same rigid card rises in scene 2. Its geometry never changes.
    for (let i = -2; i <= 2; i++) {
      star(i * 30, 490, i === 0 ? 7.5 : 5.5, i % 2 === 0 ? C.gold : '#93A286', 5);
    }
    line('#C8B78E', 1.0, () => {
      ctx.moveTo(-87, 490);
      ctx.lineTo(-76, 490);
      ctx.moveTo(76, 490);
      ctx.lineTo(87, 490);
    });
    cardGreeting(firstTitleAlpha, false);
    cardGreeting(secondTitleAlpha, true);
    ctx.restore();
  }

  function envelopeBack() {
    ctx.save();
    ctx.translate(envelopeX, envelopeY);
    const half = envelopeW / 2;
    roundRect(-half, 0, envelopeW, envelopeH, 13);
    ctx.fillStyle = '#AC6054';
    ctx.fill();
    const localTip = flapTipY - envelopeY;
    triangle(-half, 0, 0, localTip, half, 0, '#D79781');
    triangle(-half + 13, 0, 0, localTip + 12, half - 13, 0, '#DFAA95');
    line('#BD7B68', 1.5, () => {
      ctx.moveTo(-half + 5, 0);
      ctx.lineTo(0, localTip + 6);
      ctx.lineTo(half - 5, 0);
    });
    ctx.restore();
  }

  function envelopeFront() {
    ctx.save();
    ctx.translate(envelopeX, envelopeY);
    const half = envelopeW / 2;
    const h = envelopeH;
    const mouth = h * 0.48;
    roundRect(-half, 0, envelopeW, h, 13);
    ctx.clip();
    // The three panels tile one pocket. Their contact along shared folds is
    // structural, and their concave top edge correctly occludes the card.
    ctx.beginPath();
    ctx.moveTo(-half, 0);
    ctx.lineTo(-half, h);
    ctx.lineTo(half, h);
    ctx.lineTo(half, 0);
    ctx.lineTo(0, mouth);
    ctx.closePath();
    ctx.fillStyle = C.terracotta;
    ctx.fill();
    triangle(-half, 0, -half, h, 0, mouth, '#B86B5B');
    triangle(half, 0, 0, mouth, half, h, '#CC8370');
    triangle(-half, h, 0, mouth, half, h, '#BF7361');
    line('#AD6657', 1.4, () => {
      ctx.moveTo(-half + 1, 1);
      ctx.lineTo(0, mouth);
      ctx.lineTo(half - 1, 1);
      ctx.moveTo(-half + 8, h - 5);
      ctx.lineTo(0, mouth);
      ctx.lineTo(half - 8, h - 5);
    });

    const sealY = mouth + 72;
    circle(0, sealY + 2.2, 35.5, '#975449');
    circle(0, sealY, 34, '#AC6153');
    ctx.beginPath();
    ctx.arc(0, sealY, 28, 0, TAU);
    ctx.strokeStyle = '#D4AD7A';
    ctx.lineWidth = 1.3;
    ctx.stroke();
    star(0, sealY, 15.5, '#E2C18C', 5);
    trackedText('WITH LOVE', 0, h - 31, 11.5, 3.0, '#F0D9BC', 230);
    ctx.restore();
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.fillStyle = C.background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const background = ctx.createLinearGradient(0, 0, 1920, 1080);
  background.addColorStop(0, '#F9F5EC');
  background.addColorStop(0.55, '#F5F0E6');
  background.addColorStop(1, '#ECE4D5');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, 1920, 1080);

  ctx.save();
  ctx.globalAlpha = 0.46;
  roundRect(78, 74, 1764, 932, 17);
  ctx.strokeStyle = '#D8CDB7';
  ctx.lineWidth = 1.1;
  ctx.stroke();
  ctx.restore();

  const flakes = [[346,233,20],[170,423,15],[448,156,11],[1610,572,19],
    [1731,682,13],[342,934,13],[1525,932,14],[1490,124,11]];
  for (let i = 0; i < flakes.length; i++) {
    const f = flakes[i];
    snowflake(f[0], f[1], f[2], i, i % 2 === 0 ? 0.43 : 0.33);
  }
  for (let i = 0; i < 22; i++) {
    const x = 129 + ((i * 173 + 61) % 1670);
    const y = 116 + ((i * 127 + 93) % 830);
    if (x > 425 && x < 1495 && y > 135 && y < 950) continue;
    ctx.save();
    ctx.globalAlpha = 0.28 + 0.04 * Math.sin(phase + i * 0.73);
    circle(x + 2.3 * Math.sin(phase + i), y + 2.4 * Math.cos(phase + i),
      i % 3 === 0 ? 2.1 : 1.4, C.gold);
    ctx.restore();
  }

  pineSprig(278, 646, 264, -0.59, 0);
  eucalyptusSprig(231, 773, 207, 0.24, 1);
  berryTwig(319, 570, 0.15, 0);
  pineSprig(1614, 258, 276, 0.57, 2);
  eucalyptusSprig(1730, 379, 192, 1.03, 3);
  berryTwig(1676, 316, -0.18, 2);
  ribbonBow(292, 863, 0.71, 0);
  ribbonBow(1645, 782, 0.89, 2);

  // A solid grounding shadow remains below the pocket, with no blur or halo.
  ctx.save();
  ctx.globalAlpha = 0.10;
  ctx.beginPath();
  ctx.ellipse(envelopeX, envelopeY + envelopeH + 13, 480, 13, 0, 0, TAU);
  ctx.fillStyle = '#9B8B77';
  ctx.fill();
  ctx.restore();

  envelopeBack();
  card();
  envelopeFront();
  ctx.restore();
}

/*
 * NORDIC EVERGREEN GREETING FRAME
 * Pure Canvas 2D | 25 seconds | 2 scenes | Seamless loop
 * Native design: 3840 x 2160, 16:9; proportional at FHD / QHD / UHD.
 * Time Motion Studio entry point: draw(ctx, time, width, height).
 * time is already expressed in SECONDS.
 * No external images, fonts, libraries, glow, filters, or DOM access.
 * Video encoding is configured separately in EXPORT_100Mbps.json.
 */
function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !(width > 0) || !(height > 0)) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const TAU = Math.PI * 2;
  const phase = (loopT / duration) * TAU;
  const clamp = (v, low, high) => Math.max(low, Math.min(high, v));
  const lerp = (a, b, v) => a + (b - a) * v;
  const smoother = (v) => {
    const x = clamp(v, 0, 1);
    return x * x * x * (x * (x * 6 - 15) + 10);
  };
  const ramp = (low, high, v) => smoother((v - low) / (high - low));
  const transition = ramp(0.78, 1, sceneProgress);
  const frameMix = currentScene === 0 ? transition : 1 - transition;
  const cornerAlpha = 1 - ramp(0.14, 0.44, frameMix);
  const ovalAlpha = ramp(0.56, 0.86, frameMix);

  const palette = {
    ivory: '#FAF7EF',
    ivoryWarm: '#F3ECDD',
    forest: '#234D3E',
    pine: '#3E6B52',
    sage: '#6F9276',
    sageLight: '#9CB39A',
    eucalyptus: '#A4B6A0',
    eucalyptusDark: '#7E9E89',
    stem: '#5A745A',
    gold: '#B29764',
    goldDark: '#957C4E',
    goldLight: '#DBC590',
    cranberry: '#AC3C43',
    cranberryDark: '#873039',
    cranberryLight: '#CA6266',
    ink: '#284E40',
    mutedInk: '#78816A'
  };

  function strokePath(color, lineWidth, build) {
    ctx.beginPath();
    build();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function roundedRect(x, y, w, h, r) {
    const radius = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + radius, y);
    ctx.lineTo(x + w - radius, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
    ctx.lineTo(x + w, y + h - radius);
    ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
    ctx.lineTo(x + radius, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
    ctx.lineTo(x, y + radius);
    ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
  }

  function diamond(x, y, size, color, outlined) {
    ctx.beginPath();
    ctx.moveTo(x, y - size);
    ctx.lineTo(x + size, y);
    ctx.lineTo(x, y + size);
    ctx.lineTo(x - size, y);
    ctx.closePath();
    if (outlined) {
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.25;
      ctx.stroke();
    } else {
      ctx.fillStyle = color;
      ctx.fill();
    }
  }

  function star(x, y, radius, color, rotation) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rotation);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 4;
      const r = i % 2 === 0 ? radius : radius * 0.31;
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function trackedText(text, x, y, size, tracking, color, maxWidth) {
    ctx.save();
    ctx.font = '500 ' + size + 'px Arial, Helvetica, sans-serif';
    let textWidth = 0;
    for (let i = 0; i < text.length; i++) {
      textWidth += ctx.measureText(text[i]).width;
      if (i !== text.length - 1) textWidth += tracking;
    }
    const fit = Math.min(1, maxWidth / Math.max(1, textWidth));
    ctx.translate(x, y);
    ctx.scale(fit, fit);
    ctx.fillStyle = color;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    let left = -textWidth / 2;
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], left, 0);
      left += ctx.measureText(text[i]).width + tracking;
    }
    ctx.restore();
  }

  function serifText(text, x, y, size, maxWidth) {
    ctx.save();
    const family = 'Georgia, "Times New Roman", serif';
    ctx.font = 'normal ' + size + 'px ' + family;
    const measured = ctx.measureText(text).width;
    const fitSize = size * Math.min(1, maxWidth / Math.max(1, measured));
    ctx.font = 'normal ' + fitSize + 'px ' + family;
    ctx.fillStyle = palette.ink;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function pineSprig(length, id) {
    ctx.save();
    const proportional = length / 290;
    ctx.scale(proportional, proportional);
    const span = 290;
    const density = 6;
    const mainY = (u) => 5 * Math.sin(u * Math.PI * 1.5) - 4;

    strokePath(palette.stem, 3.15, () => {
      ctx.moveTo(-span / 2, -4);
      ctx.bezierCurveTo(-span * 0.18, 12, span * 0.12, -12, span / 2, -11);
    });

    function needle(x, y, dx, dy, halfWidth) {
      const len = Math.sqrt(dx * dx + dy * dy);
      const nx = -dy / len * halfWidth;
      const ny = dx / len * halfWidth;
      ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + dx * 0.42 + nx, y + dy * 0.42 + ny, x + dx, y + dy);
      ctx.quadraticCurveTo(x + dx * 0.42 - nx, y + dy * 0.42 - ny, x, y);
      ctx.closePath();
    }

    // A sprig scales uniformly during layout changes. Solid tapered needles
    // avoid a tangled outline and keep the evergreen silhouette legible.
    strokePath(palette.pine, 1.65, () => {
      for (let i = 0; i < density; i++) {
        const u = 0.07 + i * 0.151;
        const bx = -span / 2 + span * u;
        const by = mainY(u);
        const reach = 31 + 22 * Math.sin(Math.PI * u);
        for (let side = -1; side <= 1; side += 2) {
          ctx.moveTo(bx, by);
          ctx.quadraticCurveTo(bx + 12, by + side * reach * 0.5, bx + 31, by + side * reach);
        }
      }
    });
    for (let pass = 0; pass < 3; pass++) {
      ctx.beginPath();
      for (let i = 0; i < density; i++) {
        const u = 0.07 + i * 0.151;
        const bx = -span / 2 + span * u;
        const by = mainY(u);
        for (let side = -1; side <= 1; side += 2) {
          if (((i + (side > 0 ? 1 : 0) + id) % 3) !== pass) continue;
          const reach = 31 + 22 * Math.sin(Math.PI * u);
          const tx = bx + 31;
          const ty = by + side * reach;
          for (let j = 0; j < 5; j++) {
            const q = 0.20 + j * 0.172;
            const px = lerp(bx, tx, q);
            const py = lerp(by, ty, q);
            const needleLength = 24 - j * 1.8;
            needle(px, py, needleLength * 0.08, side * needleLength * 0.94, 2.25);
            needle(px, py, needleLength * 0.98, side * needleLength * 0.14, 2.15);
          }
          needle(tx - 3, ty - side * 5, 10, side * 17, 1.9);
        }
      }
      ctx.fillStyle = [palette.forest, palette.pine, palette.sage][pass];
      ctx.fill();
    }

    strokePath(palette.pine, 2.1, () => {
      for (let i = 0; i < 7; i++) {
        const x = span * 0.32 + i * span * 0.025;
        const y = -8;
        ctx.moveTo(x, y);
        ctx.lineTo(x + 17, y - 11 * (1 - i / 10));
        ctx.moveTo(x, y);
        ctx.lineTo(x + 17, y + 9 * (1 - i / 10));
      }
    });
    ctx.restore();
  }

  function eucalyptusLeaf(x, y, angle, leafScale, shade) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.scale(leafScale, leafScale);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(-14, -8, -18, -28, -4, -43);
    ctx.bezierCurveTo(8, -52, 24, -37, 22, -24);
    ctx.bezierCurveTo(22, -12, 9, -3, 0, 0);
    ctx.closePath();
    ctx.fillStyle = shade ? palette.eucalyptus : palette.eucalyptusDark;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(2, -12, 5, -29, 4, -42);
    ctx.bezierCurveTo(14, -47, 23, -34, 22, -24);
    ctx.bezierCurveTo(22, -12, 9, -3, 0, 0);
    ctx.closePath();
    ctx.fillStyle = shade ? '#B6C4AC' : '#92AF98';
    ctx.fill();
    strokePath('#779179', 1.05, () => {
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(4, -20, 4, -37);
    });
    ctx.restore();
  }

  function eucalyptusSprig(length, id) {
    ctx.save();
    const proportional = length / 220;
    ctx.scale(proportional, proportional);
    const span = 220;
    strokePath(palette.stem, 2, () => {
      ctx.moveTo(-span * 0.5, 7);
      ctx.bezierCurveTo(-span * 0.12, -10, span * 0.18, 12, span * 0.5, -7);
    });
    for (let i = 0; i < 7; i++) {
      const u = 0.11 + i * 0.12;
      const bx = -span / 2 + u * span;
      const by = 4 * Math.sin(u * Math.PI * 2);
      const side = i % 2 === 0 ? -1 : 1;
      const sway = 0.018 * Math.sin(phase + id * 0.8 + i * 0.48);
      const leafY = by + side * 9;
      strokePath(palette.stem, 1.35, () => {
        ctx.moveTo(bx - 4, by);
        ctx.lineTo(bx + 3, leafY);
      });
      eucalyptusLeaf(bx + 3, leafY, (side < 0 ? 0.39 : Math.PI - 0.4) + sway,
        0.82 + 0.14 * Math.sin(i * 1.4), (i + id) % 2 === 0);
    }
    ctx.restore();
  }

  function berryCluster(x, y, angle, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle + 0.01 * Math.sin(phase + id));
    const berries = [[-24, -13, 11], [3, -28, 12], [28, -9, 10.5], [12, 16, 11.5]];
    strokePath('#68785B', 2.1, () => {
      for (let i = 0; i < berries.length; i++) {
        ctx.moveTo(-8, 35);
        ctx.quadraticCurveTo(0, 11, berries[i][0], berries[i][1]);
      }
    });
    for (let i = 0; i < berries.length; i++) {
      const b = berries[i];
      circle(b[0], b[1] + 1.25, b[2], palette.cranberryDark);
      circle(b[0] - 0.8, b[1] - 1.2, b[2] - 0.8, palette.cranberry);
      circle(b[0] - 3, b[1] - 4.5, 2.4, palette.cranberryLight);
      circle(b[0] + 1.2, b[1] + 2.5, 1.6, palette.cranberryDark);
    }
    ctx.restore();
  }

  function ribbonBow(x, y, id) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(0.022 * Math.sin(phase + id * 0.9));
    const tailMotion = 1.7 * Math.sin(phase * 2 + id);

    // Two short ribbon tails; all folds use solid colors, never glow or blur.
    ctx.beginPath();
    ctx.moveTo(-8, 7);
    ctx.bezierCurveTo(-14, 26, -22 + tailMotion, 52, -35 + tailMotion, 69);
    ctx.lineTo(-21 + tailMotion, 66);
    ctx.lineTo(-13 + tailMotion, 75);
    ctx.bezierCurveTo(-2, 47, 2, 22, 4, 9);
    ctx.closePath();
    ctx.fillStyle = palette.cranberryDark;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(3, 8);
    ctx.bezierCurveTo(9, 31, 22 + tailMotion, 53, 34 + tailMotion, 62);
    ctx.lineTo(22 + tailMotion, 61);
    ctx.lineTo(15 + tailMotion, 71);
    ctx.bezierCurveTo(7, 55, -2, 31, -7, 10);
    ctx.closePath();
    ctx.fillStyle = palette.cranberry;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(-6, -2);
    ctx.bezierCurveTo(-26, -27, -60, -35, -57, -13);
    ctx.bezierCurveTo(-61, 9, -32, 21, -6, 8);
    ctx.closePath();
    ctx.fillStyle = palette.cranberry;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(6, -2);
    ctx.bezierCurveTo(26, -27, 60, -35, 57, -13);
    ctx.bezierCurveTo(61, 9, 32, 21, 6, 8);
    ctx.closePath();
    ctx.fillStyle = palette.cranberry;
    ctx.fill();
    strokePath(palette.cranberryDark, 1.5, () => {
      ctx.moveTo(-10, 0);
      ctx.quadraticCurveTo(-31, -8, -45, -12);
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(31, -8, 45, -12);
    });
    roundedRect(-10, -10, 20, 25, 6);
    ctx.fillStyle = palette.cranberryDark;
    ctx.fill();
    roundedRect(-7, -8, 14, 21, 4);
    ctx.fillStyle = palette.cranberry;
    ctx.fill();
    strokePath(palette.cranberryLight, 1.1, () => {
      ctx.moveTo(-3, -4);
      ctx.lineTo(-3, 7);
    });
    ctx.restore();
  }

  function bellPendant(x, y, id) {
    ctx.save();
    ctx.translate(x, y);
    const swing = 0.035 * Math.sin(phase * 2 + id * 1.1);
    ctx.rotate(swing);
    strokePath(palette.goldDark, 1.4, () => {
      ctx.moveTo(0, 0);
      ctx.lineTo(0, 57);
    });
    ctx.beginPath();
    ctx.arc(0, 63, 6, 0, TAU);
    ctx.strokeStyle = palette.goldDark;
    ctx.lineWidth = 1.8;
    ctx.stroke();
    circle(0, 114, 5.5, palette.goldDark);
    ctx.beginPath();
    ctx.moveTo(-8, 70);
    ctx.bezierCurveTo(-20, 78, -16, 92, -24, 106);
    ctx.quadraticCurveTo(0, 115, 24, 106);
    ctx.bezierCurveTo(16, 92, 20, 78, 8, 70);
    ctx.closePath();
    ctx.fillStyle = palette.gold;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-8, 71);
    ctx.bezierCurveTo(-17, 78, -13, 92, -20, 104);
    ctx.quadraticCurveTo(-10, 107, -2, 108);
    ctx.lineTo(-2, 72);
    ctx.closePath();
    ctx.fillStyle = palette.goldLight;
    ctx.fill();
    strokePath(palette.goldDark, 1.7, () => {
      ctx.moveTo(-22, 105);
      ctx.quadraticCurveTo(0, 111, 22, 105);
    });
    strokePath('#E8D7AC', 1.65, () => {
      ctx.moveTo(-10, 80);
      ctx.quadraticCurveTo(-12, 88, -14, 95);
    });
    ctx.restore();
  }

  function centralGreeting(alpha, secondScene) {
    if (alpha <= 0.0001) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    const offset = (secondScene ? 1 : -1) * 10 * (1 - alpha);
    ctx.translate(0, offset);
    trackedText(secondScene ? 'A SEASON OF TOGETHERNESS' : 'WISHING YOU A BEAUTIFUL',
      960, 344, 14, 4.1, palette.mutedInk, 620);
    serifText(secondScene ? "Season's" : 'Merry', 960, 468, secondScene ? 99 : 107, 730);
    serifText(secondScene ? 'Greetings' : 'Christmas', 960, 610, secondScene ? 137 : 142, 780);
    trackedText(secondScene ? 'PEACE  /  JOY  /  WARMTH' : 'WITH LOVE & WARM WISHES',
      960, 738, 15, 3.25, palette.mutedInk, 600);
    ctx.restore();
  }

  ctx.save();
  ctx.resetTransform ? ctx.resetTransform() : ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.fillStyle = palette.ivoryWarm;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;

  const background = ctx.createLinearGradient(0, 0, 1920, 1080);
  background.addColorStop(0, '#FAF8F1');
  background.addColorStop(0.55, '#F7F3E9');
  background.addColorStop(1, '#F0E9D9');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, 1920, 1080);

  // Fixed, faint print grain: deterministic coordinates, not temporal noise.
  ctx.save();
  ctx.globalAlpha = 0.11;
  ctx.fillStyle = '#BCAE8E';
  for (let i = 0; i < 100; i++) {
    const px = 110 + ((i * 173 + (i % 7) * 31) % 1700);
    const py = 96 + ((i * 137 + (i % 9) * 47) % 885);
    if (px > 560 && px < 1360 && py > 280 && py < 795) continue;
    ctx.beginPath();
    ctx.arc(px, py, i % 3 === 0 ? 0.85 : 0.55, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Architectural edge detail stays inside a consistent safe margin.
  ctx.save();
  ctx.globalAlpha = 0.52;
  roundedRect(86, 78, 1748, 924, 20);
  ctx.lineWidth = 1.1;
  ctx.strokeStyle = '#CFC4AD';
  ctx.stroke();
  ctx.restore();

  // Flat, restrained decorative specks; no emission, halos, or bloom.
  const flecks = [
    [184, 688, 3.1], [227, 796, 2.0], [357, 929, 3.1], [694, 958, 2.1],
    [1004, 925, 2.0], [1240, 965, 3.2], [1636, 914, 2.1], [1760, 746, 3.1],
    [1741, 408, 2.0], [1648, 186, 3.0], [1410, 113, 2.0], [1170, 134, 2.6],
    [877, 118, 2.0], [736, 169, 2.7], [126, 483, 2.0], [1800, 581, 2.0]
  ];
  for (let i = 0; i < flecks.length; i++) {
    const f = flecks[i];
    const a = phase + i * 0.89;
    ctx.save();
    ctx.globalAlpha = 0.3 + 0.08 * Math.sin(a);
    circle(f[0] + 4.5 * Math.sin(a), f[1] + 5 * Math.cos(a), f[2], palette.gold);
    ctx.restore();
  }

  // The oval's two stems stay open at the top and bottom.
  if (frameMix > 0.0001) {
    ctx.save();
    ctx.globalAlpha = frameMix * 0.58;
    ctx.strokeStyle = '#9CAA88';
    ctx.lineWidth = 2.1;
    ctx.beginPath();
    ctx.ellipse(960, 540, 655, 358, 0, 2.19, 4.12);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(960, 540, 655, 358, 0, -0.95, 0.95);
    ctx.stroke();
    ctx.restore();
  }

  // Stable anchor-to-anchor motion remains outside the title's protected area.
  // Format: corner x/y/angle/length, oval x/y/angle/length, botanical type.
  const sprigs = [
    [435, 174, -0.10, 340, 520, 228, -0.72, 240, 0],
    [235, 322, -1.10, 325, 365, 350, -1.12, 240, 0],
    [375, 252, -0.50, 270, 300, 515, -1.52, 220, 0],
    [525, 225,  0.15, 220, 324, 685,  1.25, 215, 1],
    [245, 206,  1.18, 210, 430, 817,  0.70, 220, 1],
    [188, 442, -1.36, 220, 565, 887,  0.24, 200, 0]
  ];
  for (let side = 0; side < 2; side++) {
    for (let i = 0; i < sprigs.length; i++) {
      const s = sprigs[i];
      const id = i + side * 6;
      const pathBend = Math.sin(Math.PI * frameMix);
      const horizontalMix = i === 3 ? 1 - Math.pow(1 - frameMix, 5) : frameMix;
      const verticalMix = i === 5 ? frameMix + 0.25 * pathBend : frameMix;
      const x = lerp(s[0], s[4], horizontalMix);
      const y = lerp(s[1], s[5], verticalMix);
      const angle = lerp(s[2], s[6], frameMix);
      const length = lerp(s[3], s[7], frameMix);
      const wind = 0.007 * Math.sin(phase + id * 0.74)
        + 0.003 * Math.sin(phase * 2 + id * 0.51);
      ctx.save();
      ctx.translate(side === 0 ? x : 1920 - x, side === 0 ? y : 1080 - y);
      ctx.rotate(angle + (side === 0 ? 0 : Math.PI) + wind);
      if (s[8] === 0) pineSprig(length, id);
      else eucalyptusSprig(length, id);
      ctx.restore();
    }
  }

  const berryX = lerp(405, 477, frameMix);
  const berryY = lerp(302, 286, frameMix);
  berryCluster(berryX, berryY, lerp(-0.3, -0.65, frameMix), 0);
  berryCluster(1920 - berryX, 1080 - berryY, lerp(2.8, 2.5, frameMix), 1);

  const bowX = lerp(286, 325, frameMix);
  const bowY = lerp(277, 545, frameMix);
  ribbonBow(bowX, bowY, 0);
  ribbonBow(1920 - bowX, 1080 - bowY, 2);

  const leftBellX = lerp(223, 232, frameMix);
  const leftBellY = lerp(368, 516, frameMix);
  const rightBellX = lerp(1697, 1690, frameMix);
  const rightBellY = lerp(594, 309, frameMix);
  // Short tie cords connect the hanging accents to the frame's outer foliage.
  strokePath(palette.goldDark, 1.2, () => {
    ctx.moveTo(leftBellX + lerp(12, 28, frameMix), leftBellY - 7);
    ctx.quadraticCurveTo(leftBellX + 13, leftBellY - 12, leftBellX, leftBellY);
    ctx.moveTo(rightBellX - 24, rightBellY - 6);
    ctx.quadraticCurveTo(rightBellX - 10, rightBellY - 11, rightBellX, rightBellY);
  });
  bellPendant(leftBellX, leftBellY, 0);
  bellPendant(rightBellX, rightBellY, 2);

  // Center ornament and divider remain fixed; only tiny periodic articulation.
  ctx.save();
  ctx.globalAlpha = 0.86;
  const starY = 253 + 2.4 * Math.sin(phase);
  star(960, starY, 14, palette.gold, 0.04 * Math.sin(phase));
  strokePath(palette.gold, 1.15, () => {
    ctx.moveTo(873, starY);
    ctx.lineTo(920, starY);
    ctx.moveTo(1000, starY);
    ctx.lineTo(1047, starY);
  });
  circle(856, starY, 2, palette.gold);
  circle(1064, starY, 2, palette.gold);

  strokePath(palette.gold, 1.05, () => {
    ctx.moveTo(852, 677);
    ctx.lineTo(935, 677);
    ctx.moveTo(985, 677);
    ctx.lineTo(1068, 677);
  });
  diamond(960, 677, 5.5, palette.gold, true);
  circle(945, 677, 1.45, palette.gold);
  circle(975, 677, 1.45, palette.gold);
  ctx.restore();

  // Greetings fade sequentially: their glyphs are never composited together.
  centralGreeting(cornerAlpha, false);
  centralGreeting(ovalAlpha, true);

  ctx.restore();
}

/*
 * CONCEPT 03 — WINTER VILLAGE CHRISTMAS WISHES
 * Pure Canvas 2D / 25 seconds / 2 scenes / seamless loop / 16:9.
 * Native export: 3840 x 2160. Responsive at 1920 x 1080 / 2560 x 1440.
 * Entry point: draw(ctx, time, width, height). time is in SECONDS.
 * No HTML, DOM, images, external fonts, libraries, or licensed assets.
 * No glow, bloom, blur, halos, additive blending, or emission effects.
 *
 * VIDEO ENCODER SETTINGS (Canvas itself does not set video bitrate):
 * UHD 3840 x 2160, 60 fps, 25 seconds, 1500 frames, H.264 / MOV / BT.709.
 * Set manual CBR target, minimum, maximum = 100,000,000 bits/s (100 Mbps).
 * VBV buffer = 200,000,000 bits. Disable automatic/random bitrate.
 * FFmpeg: -b:v 100M -minrate 100M -maxrate 100M -bufsize 200M
 * -x264-params nal-hrd=cbr:force-cfr=1:filler=1 -pix_fmt yuv420p
 * -g 120 -keyint_min 120 -sc_threshold 0 -fps_mode cfr
 * Render frame indices 0..1499 at time = frame_index / 60.
 * Do not append the duplicate t=25 frame. Check the encoded video
 * stream using ffprobe; an export below 100,000,000 bits/s fails the target.
 */
function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !Number.isFinite(width)
      || !Number.isFinite(height) || width <= 0 || height <= 0) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;
  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const lerp = (a, b, x) => a + (b - a) * x;
  const smooth = (x) => {
    const v = clamp(x, 0, 1);
    return v * v * v * (v * (v * 6 - 15) + 10);
  };
  const ramp = (a, b, x) => smooth((x - a) / (b - a));
  const transition = ramp(0.78, 1, sceneProgress);
  const villageMix = currentScene === 0 ? transition : 1 - transition;
  const cameraX = 150 * villageMix;
  const firstTitleAlpha = 1 - ramp(0.14, 0.44, villageMix);
  const secondTitleAlpha = ramp(0.56, 0.86, villageMix);

  const C = {
    sky: '#E8F1F5',
    snow: '#FBFCF6',
    snowShade: '#D5E3E7',
    ink: '#34596A',
    mutedInk: '#6F8B94',
    gold: '#B99861',
    roof: '#50727C',
    forest: '#37685F',
    forestDark: '#2D5853',
    sage: '#5B8170',
    cranberry: '#B75852',
    cranberryDark: '#944941',
    warmWindow: '#E8CA8D',
    windowFrame: '#5A747A',
    fence: '#95ACAD'
  };

  function line(color, thickness, build) {
    ctx.beginPath();
    build();
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function roundRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function star(x, y, radius, color, points) {
    const n = points || 4;
    ctx.beginPath();
    for (let i = 0; i < n * 2; i++) {
      const a = -Math.PI / 2 + i * Math.PI / n;
      const r = i % 2 === 0 ? radius : radius * (n === 5 ? 0.47 : 0.30);
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function trackedText(text, x, baseline, size, tracking, color, maxWidth) {
    ctx.save();
    ctx.font = '500 ' + size + 'px Arial, Helvetica, sans-serif';
    const widths = [];
    let total = Math.max(0, text.length - 1) * tracking;
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      widths.push(w);
      total += w;
    }
    const fit = Math.min(1, maxWidth / Math.max(1, total));
    ctx.translate(x, baseline);
    ctx.scale(fit, fit);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color;
    let left = -total / 2;
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], left, 0);
      left += widths[i] + tracking;
    }
    ctx.restore();
  }

  function serifText(text, x, baseline, size, maxWidth, color) {
    ctx.save();
    const family = 'Georgia, "Times New Roman", serif';
    ctx.font = 'normal ' + size + 'px ' + family;
    const measured = ctx.measureText(text).width;
    const fittedSize = size * Math.min(1, maxWidth / Math.max(1, measured));
    ctx.font = 'normal ' + fittedSize + 'px ' + family;
    ctx.fillStyle = color || C.ink;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, x, baseline);
    ctx.restore();
  }

  function flatShadow(x, y, rx, ry, opacity) {
    ctx.save();
    ctx.globalAlpha *= opacity;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    ctx.fillStyle = '#849FA8';
    ctx.fill();
    ctx.restore();
  }

  function cloud(x, y, w, id) {
    ctx.save();
    ctx.translate(x + 9 * Math.sin(phase + id), y + 1.5 * Math.cos(phase + id));
    ctx.globalAlpha *= 0.57;
    ctx.beginPath();
    ctx.moveTo(-w / 2, 12);
    ctx.bezierCurveTo(-w * 0.55, -1, -w * 0.35, -8, -w * 0.27, 0);
    ctx.bezierCurveTo(-w * 0.26, -27, -w * 0.07, -34, w * 0.04, -13);
    ctx.bezierCurveTo(w * 0.14, -26, w * 0.34, -18, w * 0.35, 1);
    ctx.bezierCurveTo(w * 0.51, -5, w * 0.58, 12, w * 0.45, 17);
    ctx.lineTo(-w * 0.45, 17);
    ctx.quadraticCurveTo(-w * 0.51, 17, -w / 2, 12);
    ctx.closePath();
    ctx.fillStyle = '#F7FAF7';
    ctx.fill();
    ctx.restore();
  }

  function pineLayer(w, top, bottom, fill) {
    ctx.beginPath();
    ctx.moveTo(0, top);
    ctx.bezierCurveTo(-w * 0.09, top + 18, -w * 0.31, bottom - 28, -w / 2, bottom - 2);
    ctx.quadraticCurveTo(-w / 2 - 2, bottom + 4, -w / 2 + 6, bottom + 6);
    ctx.quadraticCurveTo(0, bottom + 13, w / 2 - 6, bottom + 6);
    ctx.quadraticCurveTo(w / 2 + 2, bottom + 4, w / 2, bottom - 2);
    ctx.bezierCurveTo(w * 0.31, bottom - 28, w * 0.09, top + 18, 0, top);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function snowOnPine(w, top, depth) {
    ctx.beginPath();
    ctx.moveTo(0, top);
    ctx.quadraticCurveTo(-w * 0.055, top + 12, -w * 0.18, top + depth);
    ctx.quadraticCurveTo(-w * 0.09, top + depth + 5, -w * 0.04, top + depth - 1);
    ctx.quadraticCurveTo(w * 0.04, top + depth + 5, w * 0.18, top + depth);
    ctx.quadraticCurveTo(w * 0.055, top + 12, 0, top);
    ctx.closePath();
    ctx.fillStyle = '#EEF4ED';
    ctx.fill();
  }

  function smallPine(x, base, w, h, id, distant) {
    ctx.save();
    ctx.translate(x, base);
    // Rotation around the trunk base keeps every crown and snow cap proportional.
    ctx.rotate((distant ? 0.004 : 0.006) * Math.sin(phase + id * 0.83));
    ctx.fillStyle = distant ? '#B5CBCF' : '#6F8C80';
    roundRect(-w * 0.07, -h * 0.19, w * 0.14, h * 0.19, 2);
    ctx.fill();
    const dark = distant ? '#ADC8CC' : C.forestDark;
    const mid = distant ? '#B9D0D1' : C.sage;
    pineLayer(w * 0.62, -h, -h * 0.52, mid);
    pineLayer(w * 0.84, -h * 0.77, -h * 0.30, dark);
    pineLayer(w, -h * 0.54, -h * 0.12, mid);
    if (!distant) {
      snowOnPine(w * 0.62, -h, h * 0.08);
      snowOnPine(w * 0.84, -h * 0.77, h * 0.08);
      snowOnPine(w, -h * 0.54, h * 0.08);
    }
    ctx.restore();
  }

  function windowPane(x, y, w, h, id, frameColor) {
    const pulse = 0.5 + 0.5 * Math.sin(phase + id * 0.72);
    const r = Math.round(lerp(225, 235, pulse));
    const g = Math.round(lerp(191, 206, pulse));
    const b = Math.round(lerp(127, 151, pulse));
    roundRect(x - w / 2 - 3, y - 3, w + 6, h + 6, 3);
    ctx.fillStyle = frameColor || C.windowFrame;
    ctx.fill();
    roundRect(x - w / 2, y, w, h, 1.5);
    ctx.fillStyle = 'rgb(' + r + ',' + g + ',' + b + ')';
    ctx.fill();
    line(frameColor || C.windowFrame, 2.1, () => {
      ctx.moveTo(x, y + 1);
      ctx.lineTo(x, y + h - 1);
      ctx.moveTo(x - w / 2 + 1, y + h * 0.47);
      ctx.lineTo(x + w / 2 - 1, y + h * 0.47);
    });
    roundRect(x - w / 2 - 5, y + h + 3, w + 10, 5, 2.5);
    ctx.fillStyle = C.snow;
    ctx.fill();
  }

  function house(x, bottom, w, wallH, roofH, paint, roofPaint, id, twoStoreys) {
    const half = w / 2;
    const top = bottom - wallH;
    const peak = top - roofH;
    flatShadow(x, bottom + 8, half + 7, 8, 0.12);
    ctx.save();
    ctx.translate(x, 0);

    // Chimney stays behind the roof, with a separate attached snow cap.
    const chimneyX = -w * 0.28;
    const chimneyY = peak + 12;
    roundRect(chimneyX - 10, chimneyY, 20, roofH * 0.7, 2);
    ctx.fillStyle = roofPaint;
    ctx.fill();
    roundRect(chimneyX - 13, chimneyY - 4, 26, 8, 3);
    ctx.fillStyle = C.snow;
    ctx.fill();

    roundRect(-half, top, w, wallH, 3);
    ctx.fillStyle = paint;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-half, top);
    ctx.lineTo(0, peak + 8);
    ctx.lineTo(half, top);
    ctx.closePath();
    ctx.fillStyle = paint;
    ctx.fill();
    ctx.fillStyle = 'rgba(42,74,80,0.07)';
    ctx.fillRect(half - 12, top + 2, 12, wallH - 2);

    // Roof and its narrow snow strip share an exact triangular silhouette.
    ctx.beginPath();
    ctx.moveTo(-half - 12, top + 7);
    ctx.lineTo(0, peak);
    ctx.lineTo(half + 12, top + 7);
    ctx.lineTo(half + 8, top + 18);
    ctx.lineTo(0, peak + 15);
    ctx.lineTo(-half - 8, top + 18);
    ctx.closePath();
    ctx.fillStyle = roofPaint;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-half - 11, top + 3);
    ctx.lineTo(-2, peak - 3);
    ctx.quadraticCurveTo(0, peak - 5, 2, peak - 3);
    ctx.lineTo(half + 11, top + 3);
    ctx.quadraticCurveTo(half + 14, top + 8, half + 7, top + 10);
    ctx.lineTo(0, peak + 10);
    ctx.lineTo(-half - 7, top + 10);
    ctx.quadraticCurveTo(-half - 14, top + 8, -half - 11, top + 3);
    ctx.closePath();
    ctx.fillStyle = C.snow;
    ctx.fill();
    line('#E1EAE7', 1.1, () => {
      ctx.moveTo(-half - 6, top + 10);
      ctx.lineTo(0, peak + 10);
      ctx.lineTo(half + 6, top + 10);
    });

    // Attic window: its ring, crossbar and glass remain contained in the gable.
    circle(0, top - roofH * 0.38, 13, roofPaint);
    circle(0, top - roofH * 0.38, 9.8, '#E5C888');
    line(roofPaint, 1.5, () => {
      ctx.moveTo(0, top - roofH * 0.38 - 9);
      ctx.lineTo(0, top - roofH * 0.38 + 9);
      ctx.moveTo(-9, top - roofH * 0.38);
      ctx.lineTo(9, top - roofH * 0.38);
    });

    if (twoStoreys) {
      for (let i = -1; i <= 1; i++) windowPane(i * 52, top + 35, 29, 40, id * 5 + i + 2, roofPaint);
      windowPane(-52, top + 112, 31, 40, id * 5 + 4, roofPaint);
      windowPane(52, top + 112, 31, 40, id * 5 + 5, roofPaint);
      line('rgba(51,83,85,0.11)', 1.2, () => {
        ctx.moveTo(-half + 10, top + 91);
        ctx.lineTo(half - 10, top + 91);
      });
    } else {
      windowPane(-w * 0.27, top + 47, 28, 41, id * 5, roofPaint);
      windowPane(w * 0.27, top + 47, 28, 41, id * 5 + 1, roofPaint);
    }

    const doorW = twoStoreys ? 43 : 38;
    const doorH = 67;
    roundRect(-doorW / 2 - 3, bottom - doorH - 3, doorW + 6, doorH + 3, 3);
    ctx.fillStyle = roofPaint;
    ctx.fill();
    roundRect(-doorW / 2, bottom - doorH, doorW, doorH, 2);
    ctx.fillStyle = id % 2 === 0 ? '#3D6867' : '#865B51';
    ctx.fill();
    roundRect(-doorW * 0.28, bottom - doorH + 7, doorW * 0.56, 17, 2);
    ctx.fillStyle = '#DCC896';
    ctx.fill();
    circle(doorW * 0.30, bottom - 25, 2.1, C.gold);
    ctx.beginPath();
    ctx.arc(0, bottom - 32, 7.7, 0, TAU);
    ctx.strokeStyle = '#8FA480';
    ctx.lineWidth = 3.8;
    ctx.stroke();
    circle(-3.5, bottom - 27.5, 2, C.cranberry);
    circle(3.5, bottom - 27.5, 2, C.cranberry);
    roundRect(-doorW * 0.70, bottom, doorW * 1.4, 6, 2);
    ctx.fillStyle = '#DEE7E6';
    ctx.fill();
    roundRect(-doorW * 0.80, bottom + 5, doorW * 1.6, 5, 2);
    ctx.fillStyle = '#EDF2ED';
    ctx.fill();
    ctx.restore();
  }

  function fence(startX, base, length, posts) {
    const step = length / (posts - 1);
    line(C.fence, 5, () => {
      ctx.moveTo(startX, base - 28);
      ctx.lineTo(startX + length, base - 28);
      ctx.moveTo(startX, base - 11);
      ctx.lineTo(startX + length, base - 11);
    });
    for (let i = 0; i < posts; i++) {
      const x = startX + i * step;
      roundRect(x - 4, base - 42, 8, 43, 2);
      ctx.fillStyle = '#88A3A6';
      ctx.fill();
      roundRect(x - 6, base - 46, 12, 7, 3);
      ctx.fillStyle = C.snow;
      ctx.fill();
    }
  }

  function christmasTree(x, base) {
    flatShadow(x, base + 9, 112, 9, 0.13);
    ctx.save();
    ctx.translate(x, base);
    ctx.rotate(0.0035 * Math.sin(phase));
    roundRect(-13, -55, 26, 57, 2);
    ctx.fillStyle = '#8A8270';
    ctx.fill();
    // Three intentional nested crown tiers form one coherent evergreen.
    pineLayer(139, -306, -204, C.sage);
    pineLayer(180, -254, -131, C.forest);
    pineLayer(222, -191, -36, C.forestDark);
    snowOnPine(139, -306, 22);
    snowOnPine(180, -254, 24);
    snowOnPine(222, -191, 24);
    line('#D2B678', 2.5, () => {
      ctx.moveTo(-38, -237);
      ctx.quadraticCurveTo(0, -220, 38, -237);
      ctx.moveTo(-56, -163);
      ctx.quadraticCurveTo(0, -139, 56, -163);
      ctx.moveTo(-70, -82);
      ctx.quadraticCurveTo(0, -53, 70, -82);
    });
    const ornaments = [
      [-16,-262,5.5,0], [26,-224,5.5,1], [-26,-191,6,1],
      [18,-165,6,0], [54,-139,5.5,2], [-35,-109,6,0],
      [-19,-85,6,1], [34,-60,6,0], [77,-47,5.5,1]
    ];
    const colors = [C.cranberry, '#D7BE8C', '#87A899'];
    for (let i = 0; i < ornaments.length; i++) {
      const p = ornaments[i];
      circle(p[0], p[1], p[2], colors[p[3]]);
      circle(p[0] - 1.6, p[1] - 1.8, 1.3, p[3] === 0 ? '#D28B76' : '#EEE0BA');
    }
    star(0, -324, 17, '#C7A56D', 5);
    ctx.restore();
  }

  function greetingSign(x, base, alpha) {
    if (alpha <= 0.0001) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    flatShadow(x, base + 5, 56, 5, 0.10);
    roundRect(x - 39, base - 95, 7, 97, 2);
    ctx.fillStyle = '#91A5A0';
    ctx.fill();
    roundRect(x + 32, base - 95, 7, 97, 2);
    ctx.fill();
    roundRect(x - 54, base - 112, 108, 75, 7);
    ctx.fillStyle = '#52786D';
    ctx.fill();
    roundRect(x - 49, base - 107, 98, 65, 4);
    ctx.fillStyle = '#F2EDDA';
    ctx.fill();
    roundRect(x - 56, base - 116, 112, 8, 4);
    ctx.fillStyle = C.snow;
    ctx.fill();
    trackedText('JOY TO', x, base - 79, 11.5, 1.0, '#41675B', 90);
    trackedText('THE WORLD', x, base - 59, 10.5, 0.55, '#41675B', 91);
    ctx.restore();
  }

  function greeting(alpha, second) {
    if (alpha <= 0.0001) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.translate(0, (second ? 1 : -1) * 9 * (1 - alpha));
    trackedText(second ? 'FROM OUR VILLAGE TO YOUR HOME' : 'WISHING YOU A BEAUTIFUL',
      960, 113, 13.5, 3.2, C.mutedInk, 770);
    serifText(second ? 'Joy to' : 'Merry', 960, 253, second ? 103 : 105, 800);
    serifText(second ? 'the World' : 'Christmas', 960, 393, second ? 125 : 133, 820);
    line(C.gold, 1.1, () => {
      ctx.moveTo(846, 432);
      ctx.lineTo(933, 432);
      ctx.moveTo(987, 432);
      ctx.lineTo(1074, 432);
    });
    star(960, 432, 5.7, C.gold, 4);
    circle(944, 432, 1.3, C.gold);
    circle(976, 432, 1.3, C.gold);
    trackedText(second ? 'WISHING YOU PEACE & HAPPINESS' : 'A SEASON OF PEACE, JOY & TOGETHERNESS',
      960, 477, 13.5, 2.45, C.mutedInk, 810);
    ctx.restore();
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.fillStyle = C.sky;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const skyGradient = ctx.createLinearGradient(0, 0, 0, 1080);
  skyGradient.addColorStop(0, '#F1F6F8');
  skyGradient.addColorStop(0.50, '#DAE9EF');
  skyGradient.addColorStop(1, '#C6DEE5');
  ctx.fillStyle = skyGradient;
  ctx.fillRect(0, 0, 1920, 1080);
  cloud(265 - cameraX * 0.10, 146, 245, 0);
  cloud(1650 - cameraX * 0.10, 164, 265, 2);

  // Open sky above the landscape keeps both greetings unobstructed.
  ctx.save();
  ctx.translate(-cameraX * 0.18, 0);
  ctx.beginPath();
  ctx.moveTo(-90, 681);
  ctx.bezierCurveTo(170, 587, 373, 596, 621, 673);
  ctx.bezierCurveTo(852, 573, 1081, 605, 1292, 672);
  ctx.bezierCurveTo(1510, 574, 1693, 610, 2010, 646);
  ctx.lineTo(2010, 899);
  ctx.lineTo(-90, 899);
  ctx.closePath();
  ctx.fillStyle = '#D0E1E6';
  ctx.fill();
  ctx.restore();

  // Fixed-depth forest; the gentle base pivot never changes tree proportions.
  ctx.save();
  ctx.translate(-cameraX * 0.32, 0);
  const forest = [
    [196,755,72,157], [425,757,66,137], [824,753,80,143],
    [945,755,57,120], [1255,754,70,144], [1518,758,72,160], [1776,755,68,144]
  ];
  for (let i = 0; i < forest.length; i++) {
    const p = forest[i];
    smallPine(p[0], p[1], p[2], p[3], i + 10, true);
  }
  ctx.restore();

  ctx.beginPath();
  ctx.moveTo(0, 783);
  ctx.bezierCurveTo(325, 729, 586, 749, 878, 784);
  ctx.bezierCurveTo(1205, 724, 1518, 766, 1920, 753);
  ctx.lineTo(1920, 1080);
  ctx.lineTo(0, 1080);
  ctx.closePath();
  const snowGradient = ctx.createLinearGradient(0, 756, 0, 1080);
  snowGradient.addColorStop(0, '#FAFCF7');
  snowGradient.addColorStop(0.55, '#F5F8F4');
  snowGradient.addColorStop(1, '#EAF1F1');
  ctx.fillStyle = snowGradient;
  ctx.fill();

  // A calm S-curve leads from the village square toward the foreground.
  ctx.save();
  ctx.translate(-cameraX, 0);
  ctx.beginPath();
  ctx.moveTo(1033, 857);
  ctx.bezierCurveTo(1009, 890, 951, 920, 951, 963);
  ctx.bezierCurveTo(951, 1009, 1010, 1048, 1102, 1080);
  ctx.lineTo(1272, 1080);
  ctx.bezierCurveTo(1118, 1022, 1037, 1002, 1037, 961);
  ctx.bezierCurveTo(1037, 923, 1087, 893, 1109, 859);
  ctx.closePath();
  ctx.fillStyle = '#D9E6E7';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(1055, 859);
  ctx.bezierCurveTo(1027, 891, 978, 925, 978, 963);
  ctx.bezierCurveTo(978, 1005, 1038, 1044, 1160, 1080);
  ctx.strokeStyle = '#E9F1EE';
  ctx.lineWidth = 2.1;
  ctx.stroke();

  // Plaza pavers are contained below the tree and sign, and fade in gradually.
  ctx.save();
  ctx.globalAlpha = ramp(0.15, 0.85, villageMix) * 0.64;
  ctx.beginPath();
  ctx.ellipse(1082, 882, 183, 25, 0, 0, TAU);
  ctx.fillStyle = '#E4EBE8';
  ctx.fill();
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 6; col++) {
      const x = 953 + col * 46 + (row % 2) * 15;
      const y = 880 + row * 12;
      roundRect(x, y, 34, 4, 2);
      ctx.fillStyle = '#BECFD0';
      ctx.fill();
    }
  }
  ctx.restore();

  const houses = [
    [340,866,176,163,87,'#C57F70','#596F77',0,false],
    [610,865,184,205,110,'#D4D8C5','#50716D',1,true],
    [1410,868,184,181,96,'#9AB6B5','#526E78',2,false],
    [1710,866,166,160,78,'#DCCBB2','#7E756A',3,false]
  ];
  for (let i = 0; i < houses.length; i++) house(...houses[i]);
  fence(450, 867, 46, 3);
  fence(725, 862, 17, 2);
  flatShadow(805, 865, 52, 6, 0.11);
  smallPine(805, 860, 96, 196, 1, false);
  flatShadow(1560, 869, 31, 5, 0.10);
  smallPine(1560, 862, 54, 154, 3, false);
  christmasTree(1110, 866);
  greetingSign(925, 892, ramp(0.28, 0.78, villageMix));
  ctx.restore();

  // Periodic snowfall wraps only beyond the visible canvas, with full integer
  // cycles per loop. A smooth exclusion mask keeps the greeting area clear.
  for (let i = 0; i < 58; i++) {
    const seed = ((i * 149 + 37) % 997) / 997;
    const cycles = i % 7 === 0 ? 2 : 1;
    const travel = (loopT / duration * cycles + seed) % 1;
    const y = -22 + travel * 1124;
    const baseX = 78 + ((i * 281 + 41) % 1764);
    const x = baseX + 10 * Math.sin(phase + i * 0.71);
    const radius = 1.4 + (i % 4) * 0.45;
    const protectedX = ramp(492, 526, x) * (1 - ramp(1394, 1428, x));
    const protectedY = ramp(65, 97, y) * (1 - ramp(488, 519, y));
    const alpha = (0.48 + 0.08 * (i % 3)) * (1 - protectedX * protectedY);
    if (alpha < 0.001) continue;
    ctx.save();
    ctx.globalAlpha = alpha;
    circle(x, y, radius, '#FFFFFF');
    ctx.restore();
  }

  // Sequential fades prevent the two greeting layouts from ever overlapping.
  greeting(firstTitleAlpha, false);
  greeting(secondTitleAlpha, true);
  ctx.restore();
}

/*
 * CONCEPT 02 — GOLDEN ORNAMENT GREETING GALLERY
 * Canvas 2D only. No DOM, images, external fonts, or libraries.
 * 25 seconds / 2 scenes / seamless loop / 16:9 / UHD 3840 x 2160.
 * Also proportional at FHD 1920 x 1080 and QHD 2560 x 1440.
 * Entry point: draw(ctx, time, width, height). time is in SECONDS.
 *
 * VIDEO EXPORT REFERENCE — configure these in your VIDEO ENCODER:
 * 3840 x 2160, 60 fps, 25 seconds, 1500 frames, H.264, MOV, BT.709.
 * CBR target / minimum / maximum: 100,000,000 bits/second (100 Mbps).
 * VBV buffer: 200,000,000 bits. No audio. Disable random bitrate.
 * FFmpeg flags: -b:v 100M -minrate 100M -maxrate 100M -bufsize 200M
 * -x264-params nal-hrd=cbr:force-cfr=1:filler=1 -pix_fmt yuv420p
 * -g 120 -keyint_min 120 -sc_threshold 0 -fps_mode cfr
 * Frame indices: 0..1499; time = frame_index / 60. Do not append t=25.
 * Canvas does not set video bitrate. Verify the encoded VIDEO stream
 * with ffprobe; reject an export measured below 100,000,000 bits/s.
 *
 * All shading is confined to opaque ornament surfaces. No glow,
 * bloom, blur, emission, additive blending, or halo effects are used.
 */
function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !Number.isFinite(width)
      || !Number.isFinite(height) || width <= 0 || height <= 0) return;

  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1080;
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;
  const clamp = (x, low, high) => Math.max(low, Math.min(high, x));
  const lerp = (a, b, x) => a + (b - a) * x;
  const smooth = (x) => {
    const v = clamp(x, 0, 1);
    return v * v * v * (v * (v * 6 - 15) + 10);
  };
  const ramp = (a, b, x) => smooth((x - a) / (b - a));
  const sceneTransition = ramp(0.78, 1, sceneProgress);
  const galleryMix = currentScene === 0 ? sceneTransition : 1 - sceneTransition;
  const horizontalMix = 1 - Math.pow(1 - galleryMix, 4);
  const verticalMix = galleryMix * galleryMix;
  const firstTitleAlpha = 1 - ramp(0.15, 0.44, galleryMix);
  const secondTitleAlpha = ramp(0.56, 0.85, galleryMix);

  const C = {
    navy: '#11283A',
    navyDeep: '#0D2030',
    navySoft: '#19364A',
    gold: '#C8AD79',
    goldLight: '#E5D0A5',
    goldDeep: '#9D8153',
    goldLine: '#A88F62',
    cream: '#F2EBDB',
    creamShade: '#DDD0B5',
    inkOnGold: '#756039',
    text: '#E9D7B0',
    subtext: '#B3B2A0',
    frame: '#617061'
  };

  function line(color, thickness, build) {
    ctx.beginPath();
    build();
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  function circle(x, y, r, fill) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function roundRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function starPath(radius, points, innerRatio) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const a = -Math.PI / 2 + i * Math.PI / points;
      const r = i % 2 === 0 ? radius : radius * innerRatio;
      const x = Math.cos(a) * r;
      const y = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
  }

  function smallStar(x, y, radius, rotation, color) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rotation);
    starPath(radius, 4, 0.3);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  function diamondPath(w, h) {
    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.lineTo(w, 0);
    ctx.lineTo(0, h);
    ctx.lineTo(-w, 0);
    ctx.closePath();
  }

  function dropPath(w, h) {
    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.bezierCurveTo(w * 0.28, -h * 0.60, w, -h * 0.32, w, h * 0.12);
    ctx.bezierCurveTo(w, h * 0.57, w * 0.38, h, 0, h);
    ctx.bezierCurveTo(-w * 0.38, h, -w, h * 0.57, -w, h * 0.12);
    ctx.bezierCurveTo(-w, -h * 0.32, -w * 0.28, -h * 0.60, 0, -h);
    ctx.closePath();
  }

  function trackedText(text, x, baseline, size, tracking, color, maxWidth) {
    ctx.save();
    ctx.font = '500 ' + size + 'px Arial, Helvetica, sans-serif';
    const glyphWidths = [];
    let total = Math.max(0, text.length - 1) * tracking;
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      glyphWidths.push(w);
      total += w;
    }
    const fit = Math.min(1, maxWidth / Math.max(1, total));
    ctx.translate(x, baseline);
    ctx.scale(fit, fit);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color;
    let start = -total / 2;
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], start, 0);
      start += glyphWidths[i] + tracking;
    }
    ctx.restore();
  }

  function serifText(text, x, baseline, size, maxWidth) {
    ctx.save();
    const family = 'Georgia, "Times New Roman", serif';
    ctx.font = 'normal ' + size + 'px ' + family;
    const measured = ctx.measureText(text).width;
    const fittedSize = size * Math.min(1, maxWidth / Math.max(1, measured));
    ctx.font = 'normal ' + fittedSize + 'px ' + family;
    ctx.fillStyle = C.text;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText(text, x, baseline);
    ctx.restore();
  }

  function cap(top, capWidth) {
    const w = capWidth;
    roundRect(-w / 2, top - 12, w, 14, 3);
    ctx.fillStyle = C.goldDeep;
    ctx.fill();
    roundRect(-w / 2 + 2, top - 11, w - 4, 9, 2);
    ctx.fillStyle = C.gold;
    ctx.fill();
    line(C.goldLight, 1.1, () => {
      for (let i = -1; i <= 1; i++) {
        ctx.moveTo(i * w * 0.20, top - 10);
        ctx.lineTo(i * w * 0.20, top - 4);
      }
    });
    ctx.beginPath();
    ctx.arc(0, top - 18, 5.4, 0, TAU);
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 1.7;
    ctx.stroke();
  }

  function goldBall(radius, variant, id) {
    const r = radius;
    const surface = ctx.createLinearGradient(-r, -r * 0.2, r, r * 0.6);
    surface.addColorStop(0, '#CEB888');
    surface.addColorStop(0.55, '#E0CAA0');
    surface.addColorStop(1, '#BA9B65');
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fillStyle = surface;
    ctx.fill();
    ctx.strokeStyle = C.goldDeep;
    ctx.lineWidth = 1.7;
    ctx.stroke();

    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, r - 2, 0, TAU);
    ctx.clip();
    ctx.rotate(0.018 * Math.sin(phase + id * 0.6));
    if (variant === 0) {
      // Curved meridians are opaque engraving, not luminous highlights.
      line('#AA8B57', 1.8, () => {
        for (let k = -2; k <= 2; k++) {
          const x = k * r * 0.32;
          ctx.moveTo(x * 0.42, -r - 2);
          ctx.bezierCurveTo(x * 1.55, -r * 0.45, x * 1.55, r * 0.45, x * 0.42, r + 2);
        }
      });
      line('#E9D9B7', 1.2, () => {
        ctx.moveTo(-r, -r * 0.14);
        ctx.quadraticCurveTo(0, r * 0.03, r, -r * 0.14);
        ctx.moveTo(-r, r * 0.2);
        ctx.quadraticCurveTo(0, r * 0.4, r, r * 0.2);
      });
    } else {
      line('#AA8B57', 1.6, () => {
        for (let k = -3; k <= 3; k++) {
          const y = k * r * 0.25;
          ctx.moveTo(-r - 5, y);
          ctx.quadraticCurveTo(0, y + r * 0.28, r + 5, y);
        }
      });
      for (let j = 0; j < 5; j++) {
        const x = (j - 2) * r * 0.31;
        const y = r * 0.05 + (j % 2 ? r * 0.24 : -r * 0.08);
        smallStar(x, y, 5.5, 0, '#8F7649');
      }
    }
    ctx.restore();

    ctx.beginPath();
    ctx.arc(0, 0, r - 7, 0, TAU);
    ctx.strokeStyle = '#E8D7B2';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    cap(-r, 28);
  }

  function pearlBall(radius, id) {
    const r = radius;
    const fill = ctx.createLinearGradient(-r, -r, r, r);
    fill.addColorStop(0, C.cream);
    fill.addColorStop(0.65, '#EDE4D2');
    fill.addColorStop(1, C.creamShade);
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 1.7;
    ctx.stroke();
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, r - 6, 0, TAU);
    ctx.clip();
    const patternAngle = 0.016 * Math.sin(phase + id);
    ctx.rotate(patternAngle);
    const marks = [[-22,-17,8],[20,-28,5],[27,17,7],[-17,27,5],[1,4,10]];
    for (let i = 0; i < marks.length; i++) {
      const m = marks[i];
      smallStar(m[0], m[1], m[2], Math.PI / 10, C.goldDeep);
    }
    const dots = [[-35,6],[4,-39],[38,-6],[7,38],[-32,-32],[34,35]];
    for (let i = 0; i < dots.length; i++) circle(dots[i][0], dots[i][1], 1.5, C.goldDeep);
    ctx.restore();
    ctx.beginPath();
    ctx.arc(0, 0, r - 8, 0, TAU);
    ctx.strokeStyle = '#C7B387';
    ctx.lineWidth = 1;
    ctx.stroke();
    cap(-r, 25);
  }

  function facetedDiamond(w, h) {
    diamondPath(w, h);
    ctx.fillStyle = C.gold;
    ctx.fill();
    const faces = [
      [0,-h,w,0,0,0,'#E1CAA0'],
      [0,-h,-w,0,0,0,'#C4A66D'],
      [0,h,w,0,0,0,'#AD8C54'],
      [0,h,-w,0,0,0,'#D4BB89']
    ];
    for (let i = 0; i < faces.length; i++) {
      const f = faces[i];
      ctx.beginPath();
      ctx.moveTo(f[0], f[1]);
      ctx.lineTo(f[2], f[3]);
      ctx.lineTo(f[4], f[5]);
      ctx.closePath();
      ctx.fillStyle = f[6];
      ctx.fill();
    }
    diamondPath(w * 0.54, h * 0.57);
    ctx.strokeStyle = '#F0DFB9';
    ctx.lineWidth = 1.3;
    ctx.stroke();
    diamondPath(w, h);
    ctx.strokeStyle = C.goldDeep;
    ctx.lineWidth = 1.4;
    ctx.stroke();
    cap(-h, 16);
  }

  function matteDrop(w, h) {
    dropPath(w, h);
    ctx.fillStyle = '#D3BA88';
    ctx.fill();
    ctx.save();
    dropPath(w, h);
    ctx.clip();
    ctx.fillStyle = '#E3CFAB';
    ctx.beginPath();
    ctx.moveTo(-5, -h);
    ctx.bezierCurveTo(-w * 0.58, -h * 0.12, -w * 0.48, h * 0.7, -2, h);
    ctx.lineTo(-w - 3, h + 3);
    ctx.lineTo(-w - 3, -h - 3);
    ctx.closePath();
    ctx.fill();
    line('#A88A54', 1.7, () => {
      ctx.moveTo(9, -h * 0.7);
      ctx.bezierCurveTo(w * 0.75, -h * 0.16, w * 0.7, h * 0.56, 8, h * 0.82);
      ctx.moveTo(-w, h * 0.36);
      ctx.quadraticCurveTo(0, h * 0.57, w, h * 0.36);
    });
    ctx.restore();
    dropPath(w, h);
    ctx.strokeStyle = C.goldDeep;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    cap(-h, 16);
  }

  function facetedStar(radius) {
    const r = radius;
    starPath(r, 5, 0.47);
    ctx.fillStyle = C.gold;
    ctx.fill();
    for (let i = 0; i < 5; i++) {
      const a = -Math.PI / 2 + i * TAU / 5;
      const b = a + Math.PI / 5;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
      ctx.lineTo(Math.cos(b) * r * 0.47, Math.sin(b) * r * 0.47);
      ctx.closePath();
      ctx.fillStyle = i % 2 === 0 ? '#E3CDA2' : '#AD8C55';
      ctx.fill();
    }
    starPath(r, 5, 0.47);
    ctx.strokeStyle = C.goldDeep;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, -r - 5, 4.8, 0, TAU);
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  function pendant(spec, id) {
    const x = lerp(spec[0], spec[2], horizontalMix);
    const type = spec[4];
    const y = lerp(spec[1], spec[3], type === 3 ? horizontalMix : verticalMix);
    const w = spec[5];
    const h = spec[6];
    const anchorY = 78;
    const localCenterY = y - anchorY;
    const angle = 0.012 * Math.sin(phase * 2 + id * 0.73)
      + 0.002 * Math.sin(phase * 4 + id * 0.43);
    const hookOffset = type === 0 ? -h - 10 : -h - 23.4;
    ctx.save();
    ctx.translate(x, anchorY);
    ctx.rotate(angle);
    line(C.goldLine, 1.25, () => {
      ctx.moveTo(0, 0);
      ctx.lineTo(0, Math.max(0, localCenterY + hookOffset));
    });
    ctx.translate(0, localCenterY);
    if (type === 0) facetedStar(w);
    else if (type === 1) goldBall(w, id < 3 ? 0 : 1, id);
    else if (type === 2) facetedDiamond(w, h);
    else if (type === 3) pearlBall(w, id);
    else matteDrop(w, h);
    ctx.restore();
    circle(x, anchorY, 3.3, C.goldLine);
    circle(x, anchorY, 1.5, C.navy);
  }

  function divider(y) {
    line(C.goldLine, 1.1, () => {
      ctx.moveTo(845, y);
      ctx.lineTo(935, y);
      ctx.moveTo(985, y);
      ctx.lineTo(1075, y);
    });
    circle(947, y, 1.5, C.goldLine);
    circle(973, y, 1.5, C.goldLine);
    ctx.save();
    ctx.translate(960, y);
    diamondPath(5, 5);
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 1.2;
    ctx.stroke();
    ctx.restore();
  }

  function greeting(alpha, second) {
    if (alpha <= 0.0001) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.translate(0, (second ? 1 : -1) * 11 * (1 - alpha));
    if (second) {
      smallStar(960, 313 + 1.5 * Math.sin(phase), 10.5,
        0.04 * Math.sin(phase), C.gold);
      trackedText('TO YOU & YOUR LOVED ONES', 960, 379, 15, 3.3, C.subtext, 560);
      serifText('Warm', 960, 528, 118, 650);
      serifText('Wishes', 960, 679, 144, 680);
      divider(727);
      trackedText('THIS CHRISTMAS SEASON', 960, 785, 15, 3.6, C.subtext, 560);
    } else {
      smallStar(960, 451 + 1.5 * Math.sin(phase), 10.5,
        0.04 * Math.sin(phase), C.gold);
      trackedText('A SEASON TO CELEBRATE', 960, 509, 15, 3.8, C.subtext, 560);
      serifText('Merry', 960, 648, 104, 650);
      serifText('Christmas', 960, 792, 135, 680);
      divider(835);
      trackedText('PEACE  /  JOY  /  WARMTH', 960, 891, 15, 3.0, C.subtext, 560);
    }
    ctx.restore();
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  if ('filter' in ctx) ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.fillStyle = C.navyDeep;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * unit) / 2, (height - 1080 * unit) / 2);
  ctx.scale(unit, unit);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const background = ctx.createLinearGradient(0, 0, 1920, 1080);
  background.addColorStop(0, '#172F42');
  background.addColorStop(0.50, '#11283A');
  background.addColorStop(1, '#0D2232');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, 1920, 1080);

  // The background print pattern is fixed, so there is no temporal noise.
  ctx.save();
  ctx.globalAlpha = 0.10;
  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 15; col++) {
      const x = 120 + col * 120 + (row % 2) * 18;
      const y = 132 + row * 100;
      if (x > 580 && x < 1340 && y > 390 && y < 935) continue;
      circle(x, y, 0.75, '#9AA693');
    }
  }
  ctx.restore();

  // A thin gallery frame and mounting rail keep all hanging accents grounded.
  ctx.save();
  ctx.globalAlpha = 0.38;
  roundRect(76, 66, 1768, 948, 12);
  ctx.strokeStyle = C.frame;
  ctx.lineWidth = 1.1;
  ctx.stroke();
  ctx.restore();
  line('#596657', 1.25, () => {
    ctx.moveTo(126, 78);
    ctx.lineTo(1794, 78);
  });
  circle(126, 78, 2.8, C.goldLine);
  circle(1794, 78, 2.8, C.goldLine);

  // Small gold print marks move slowly without changing size or flashing.
  const accents = [
    [142, 354, 5], [598, 192, 4], [823, 168, 3.5], [1097, 157, 3.5],
    [1322, 186, 4], [1778, 358, 5], [116, 822, 4], [1804, 818, 4],
    [269, 933, 3.5], [1651, 935, 3.5]
  ];
  for (let i = 0; i < accents.length; i++) {
    const a = accents[i];
    ctx.save();
    ctx.globalAlpha = 0.36 + 0.055 * Math.sin(phase + i * 0.65);
    smallStar(a[0] + 2.4 * Math.sin(phase + i), a[1] + 3 * Math.cos(phase + i),
      a[2], 0.045 * Math.sin(phase + i), C.goldLine);
    ctx.restore();
  }

  // x/y in scene 1, x/y in scene 2, shape, half-width/radius, half-height.
  // Separate x columns prevent both body collisions and crossed suspension cords.
  // Horizontal travel leads vertical travel, keeping the title area clear.
  const ornaments = [
    [255, 244, 175, 586, 0, 57, 57],
    [467, 346, 378, 330, 1, 82, 82],
    [704, 218, 550, 718, 2, 50, 89],
    [960, 304, 960, 182, 3, 68, 68],
    [1216, 229, 1370, 718, 4, 50, 85],
    [1453, 346, 1542, 330, 1, 82, 82],
    [1665, 244, 1745, 586, 0, 57, 57]
  ];
  for (let i = 0; i < ornaments.length; i++) pendant(ornaments[i], i);

  // Static lower print detail supports the composition without adding clutter.
  ctx.save();
  ctx.globalAlpha = 0.46;
  line(C.goldLine, 1.05, () => {
    ctx.moveTo(665, 965);
    ctx.lineTo(892, 965);
    ctx.moveTo(1028, 965);
    ctx.lineTo(1255, 965);
  });
  for (let i = -2; i <= 2; i++) circle(960 + i * 14, 965, i === 0 ? 2.3 : 1.2, C.gold);
  ctx.restore();

  // These alpha ranges do not intersect; the two greetings never overlap.
  greeting(firstTitleAlpha, false);
  greeting(secondTitleAlpha, true);
  ctx.restore();
}
